window.__Q=window.__Q||{};window.__Q["tcm/2/B1"]=[{"q":"脉象极软而沉细是","o":["虚脉","紧脉","微脉","弱脉","濡脉"],"a":3,"e":"弱脉沉细而极软，须重按始得且按之无力，主气血不足、阳气虚衰，脉体细小与柔软并存是其要点。微脉极细极软、若有若无，较之更细更弱；濡脉浮而细软，位在浮分而非沉分；虚脉举之无力、按之空豁，三部皆无力而不专沉细"},{"q":"气机阻滞所致的疼痛是","o":["绞痛","刺痛","胀痛","隐痛","重痛"],"a":2,"e":"胀痛为气机阻滞、升降失常，胀甚于痛、走窜攻撑、痛无定处，是气滞疼痛特点。刺痛如针刺、痛处固定属瘀血；绞痛剧烈如绞，多为有形实邪阻闭胆腑或心脉；隐痛绵绵、喜按属虚；重痛沉重困着，多湿邪困阻清阳"},{"q":"芤脉的脉象特征是","o":["浮而细软","浮大中空","浮大有力","浮散无根","浮而搏指，如按鼓皮"],"a":1,"e":"芤脉浮大中空、边实中虚，如按葱管，主失血、伤阴，血海空虚而阳气浮越于外。浮而细软为濡脉，主虚湿；浮大有力为洪脉，主热盛；浮散无根为散脉，主元气离散；浮而搏指、如按鼓皮为革脉，主亡血失精"},{"q":"洪脉的脉象特征是","o":["浮而细软","浮大中空","浮大有力","浮散无根","浮而搏指，如按鼓皮"],"a":2,"e":"洪脉脉体宽大、充实有力、来盛去衰，主气分热盛、邪热亢盛于内而外显于脉。浮大中空是芤脉，主失血；浮而细软是濡脉，主虚湿；浮散无根是散脉，主元气离散；革脉浮而搏指、外坚中空如按鼓皮，主精血亡失"},{"q":"革脉的脉象特征是","o":["浮而细软","浮大中空","浮大有力","浮散无根","浮而搏指，如按鼓皮"],"a":4,"e":"革脉浮而搏指、中空外坚、如按鼓皮，主亡血、失精、半产、漏下，精血内虚而阳气外越。芤脉浮大中空如按葱管，边实中虚但不如革脉绷急；洪脉浮大有力、来盛去衰；濡脉浮而细软；散脉浮散无根、至数不齐"},{"q":"常随体位而改变的病理产物是","o":["痰","饮","水","湿","脓"],"a":1,"e":"饮为水液停积于局部腔隙，质清稀，随所在部位或体位变动而表现各异，故常随体位改变。湿弥散全身、重着黏滞，无明显流动定位；痰稠厚，多流窜后停积肺与经络；水泛溢肌肤为肿；脓为热毒腐化而成"},{"q":"常弥浸于全身的病理产物是","o":["痰","饮","水","湿","脓"],"a":3,"e":"湿性弥散、重着、黏滞，浸淫全身肌肉关节，故常弥漫全身而无定处，阻遏气机、困阻清阳。饮清稀，停于胃肠胸胁等局部且随体位变动；痰稠黏，流窜后停积局部；脓为热壅血肉腐化；水多泛溢肌肤。湿之弥漫有别于痰饮之局部停积"},{"q":"可流窜而停积于某些部位的病理产物是","o":["痰","饮","水","湿","脓"],"a":0,"e":"痰稠厚黏滞，可随气机流窜，停积于肺、心包、经络、瘰疬等处，见证多样，故能流窜而停积于某些部位。饮清稀，多停胃肠、胸胁、心下等腔隙，随体位改变；湿弥散全身、重着困阻；水泛肌肤为肿；脓成于局部热毒腐化"},{"q":"患者因长期运动后喝冷饮，近期出现胃脘冷痛、喜温喜按，偶有畏寒肢冷、倦怠乏力，舌淡胖嫩，脉沉迟无力。诊为","o":["胃气虚证","胃阳虚证","胃阴虚证","胃热炽盛证","饮停胃肠证"],"a":1,"e":"胃阳虚证因胃阳不足、虚寒内生，胃脘冷痛、喜温喜按，兼畏寒肢冷、倦怠乏力、舌淡胖嫩、脉沉迟无力。胃气虚仅食少胀满、胃失和降而无明显寒象；胃阴虚见口干、饥不欲食、舌红少苔；胃热炽盛见灼痛、消谷善饥、苔黄脉数；饮停胃肠见水声辘辘、泛吐清水"},{"q":"患者胃脘部疼痛3天，现症见：胃脘灼痛，饮冷后症状稍缓解，消谷善饥，口臭，小便黄，大便秘结，舌红，苔黄，脉数。诊为","o":["胃气虚证","胃阳虚证","胃阴虚证","胃热炽盛证","饮停胃肠证"],"a":3,"e":"胃热炽盛证为胃中实热，胃脘灼痛、消谷善饥、口臭、小便黄、大便秘结、舌红苔黄、脉数，喜饮冷是里热求凉。胃阳虚则冷痛喜温、畏寒肢冷；胃阴虚虽饥不欲食、口干舌红少苔，但无灼痛便秘；饮停胃肠泛吐清水、水声辘辘；胃气虚食少乏力而无灼痛"},{"q":"镜面舌，色红绛者，为","o":["阴虚","血虚","气血两虚","胃阴枯竭，胃乏生气","营血大虚，阳气虚衰"],"a":3,"e":"镜面舌红绛为舌面光剥无苔、红绛鲜明，系胃阴枯竭、胃乏生气，津液不能上承于舌。气血两虚之镜面舌多淡白无华；肺肾阴虚见舌红少苔但未必光剥如镜；血虚舌淡白；营血大虚、阳气虚衰舌多淡胖嫩或光白。红绛而光剥的镜面舌独指胃阴枯竭"},{"q":"表证的寒热表现是","o":["恶寒发热","但寒不热","但热不寒","无寒热表现","寒热往来"],"a":0,"e":"表证为外邪袭表，邪正相争于肌表，卫阳被遏则恶寒、邪正抗争则发热，故恶寒发热同时并见。但寒不热为里寒证；但热不寒为里热证；寒热往来是半表半里少阳证；无寒热表现多见于里证虚证。恶寒发热并见是表证寒热的基本特征"},{"q":"半表半里证的寒热表现是","o":["恶寒发热","但寒不热","但热不寒","无寒热表现","寒热往来"],"a":4,"e":"半表半里证为邪郁少阳、枢机不利，正邪分争互有胜负，故寒热往来、交替而作而无定时。恶寒发热并见为表证；但寒不热属里寒；但热不寒属里热；无寒热表现非少阳所见。寒热往来是半表半里证寒热的特征，与表里证之持续性寒热不同"},{"q":"患者舌色淡紫而润，主病为","o":["气滞血瘀","气虚血瘀","寒凝血瘀","热灼营阴","血虚夹瘀"],"a":2,"e":"舌淡紫而润，淡主阳气不足、气血亏虚，紫为血行瘀滞，润示内无热邪，故主寒凝血瘀，阳虚寒凝、血行不畅。气滞血瘀舌多暗紫、伴胀痛；气虚血瘀舌淡紫胖嫩、气短乏力；热灼营阴舌绛紫而干；血虚夹瘀舌淡而瘦、脉细涩。淡紫而润是寒凝血瘀的典型舌象"},{"q":"患者舌色绛紫而干，主病为","o":["气滞血瘀","气虚血瘀","寒凝血瘀","热灼营阴","血虚夹瘀"],"a":3,"e":"舌绛紫而干，绛为热入营血，紫为血络瘀滞，干为津液被灼，故主热灼营阴，热盛伤津动血。寒凝血瘀舌淡紫而润；气滞血瘀舌暗紫不干；气虚血瘀舌淡紫胖嫩；血虚夹瘀舌淡瘦。绛紫而干与淡紫而润恰成寒热对照，鉴别要点在色泽深浅与润燥"},{"q":"不省人事，喉中痰鸣，证属","o":["痰蒙心神","痰浊阻肺","痰阻经络","痰凝肌肤","痰气郁结"],"a":0,"e":"痰蒙心神为痰浊内盛、蒙蔽心窍、神明失守，故不省人事、喉中痰鸣、面色晦暗、苔腻脉滑。痰浊阻肺见咳嗽痰多、胸闷喘满而神志清楚；痰阻经络见肢体麻木、半身不遂；痰凝肌肤见瘰疬痰核、皮下肿块；痰气郁结见精神抑郁、胸胁胀满而无昏迷。神昏痰鸣是痰蒙心神要点"},{"q":"精神抑郁，表情淡漠，胸胁胀痛，舌红，苔白腻，脉弦滑，证属","o":["痰蒙心神","痰浊阻肺","痰阻经络","痰凝肌肤","痰气郁结"],"a":4,"e":"痰气郁结由情志不遂、肝气郁结、痰浊内生，气痰互结于胸胁，故精神抑郁、表情淡漠、胸胁胀痛、舌红苔白腻、脉弦滑。痰蒙心神见神志昏迷、喉中痰鸣；痰浊阻肺以咳喘痰多为主；痰阻经络见麻木偏瘫；痰凝肌肤见皮下痰核。本证无神昏，以郁证表现为要"},{"q":"人之种族皮肤的正常色泽是","o":["客色","常色","恶色","善色","主色"],"a":4,"e":"主色由种族禀赋决定、终生基本不变，是人种固有的正常肤色。客色随季节气候环境而变；常色是正常面色的统称，包含主色与客色；善色为有病而面色光泽明润；恶色为有病而面色枯槁晦暗。主色强调种族先天、恒定不变，与随外境变化的客色相对"},{"q":"随季节气候不同而面色有相应变化的是","o":["客色","常色","恶色","善色","主色"],"a":0,"e":"客色指面色随季节、气候、环境等外界因素相应改变，仍属正常范围，如春青、夏赤、秋白、冬黑之类。主色为种族禀赋、终生不变；常色是正常面色总称，含主色客色；善色恶色均属病色，以光泽枯槁分善恶。客色随外界而变是区别于主色的关键"},{"q":"病人面色枯槁晦暗的是","o":["客色","常色","恶色","善色","主色"],"a":2,"e":"恶色为病人面色枯槁晦暗、毫无光泽，提示脏腑精气衰败、病情危重、预后不良。善色虽病而面色光泽明润、气血未衰；常色为健康正常面色；主色为种族固有肤色；客色随季节环境而变。善恶之辨全在有无光泽，枯槁晦暗是恶色的判断要点"},{"q":"饮停于胃肠，可见脘腹痞胀，泛吐清水，脘腹部水声辘辘，是","o":["痰饮","悬饮","支饮","溢饮","水湿"],"a":0,"e":"狭义痰饮指饮停胃肠，水饮内停、胃失和降，故脘腹痞胀、泛吐清水、脘腹部水声辘辘。悬饮停于胸胁，见肋间饱满、咳唾引痛；支饮停于心肺胸膈，见胸闷心悸、息促不得卧；溢饮溢于四肢，见身体肢节疼重。四饮以饮邪停积部位不同相区分"},{"q":"饮停于心肺，表现为胸闷，心悸，息促不得卧，是","o":["痰饮","悬饮","支饮","溢饮","水湿"],"a":2,"e":"支饮为饮停心胸膈间，饮邪上逆迫肺、心阳受遏，故胸闷、心悸、息促不得卧、其形如肿。痰饮停胃肠，见脘腹水声辘辘、泛吐清水；悬饮停胸胁，见肋间饱满、咳唾引痛；溢饮溢四肢，见身体肢节疼重。支饮病位在胸膈心肺，以喘促不得卧为特点"},{"q":"饮邪流行，溢于四肢，见身体、肢节疼重，是","o":["痰饮","悬饮","支饮","溢饮","水湿"],"a":3,"e":"溢饮为饮邪流行、溢于四肢肌肤，卫气被遏、营卫不行，故身体、肢节疼重、无汗。痰饮停胃肠，见泛吐清水、水声辘辘；悬饮停胸胁，见肋间饱满、咳唾引痛；支饮停胸膈心肺，见胸闷心悸、不得卧。溢饮以饮溢四肢、疼重无汗为特征"},{"q":"饮停胸胁，症见肋间饱满，咳唾引痛，胸闷息促，是","o":["痰饮","悬饮","支饮","溢饮","水湿"],"a":1,"e":"悬饮为饮停胸胁，气机阻滞、络脉不和，故肋间饱满、咳唾引痛、胸闷息促、转侧不利。痰饮停胃肠，见脘腹水声辘辘；支饮停胸膈心肺，见胸闷心悸、不得卧；溢饮溢四肢，见身体肢节疼重。悬饮病位在胸胁，以咳唾引痛为其辨证特征"},{"q":"患者发黄干枯，稀疏易落，多辨证为","o":["精血不足","血虚受风","疳积病","先天遗传","肾虚或血热"],"a":0,"e":"发黄干枯、稀疏易落为精血亏虚、毛发失养，多见于久病、产后、年老精血渐衰者。血虚受风见突然片状脱发、圆形光亮头皮；疳积病多见小儿发黄稀疏、形瘦；先天遗传自幼即头发稀疏；肾虚或血热多青壮年脱发、伴腰膝酸软或头皮油热。发枯稀疏责之精血不足"},{"q":"患者突然片状脱发，显露圆形或椭圆形光亮头皮而无自觉症状者，多为","o":["精血不足","血虚受风","疳积病","先天遗传","肾虚或血热"],"a":1,"e":"突然片状脱发、显露圆形或椭圆形光亮头皮而无自觉症状，即斑秃，为血虚生风、毛发失养、风邪乘虚客于发窍。精血不足见发黄干枯、缓慢稀疏；疳积病见小儿发黄稀疏羸瘦；先天遗传自幼稀疏；肾虚或血热见青壮年脱发伴腰膝酸软、头皮瘙痒油腻。突发圆形脱发是血虚受风特点"},{"q":"青壮年头发稀疏易落，有伴见症者，多为","o":["精血不足","血虚受风","疳积病","先天遗传","肾虚或血热"],"a":4,"e":"青壮年头发稀疏易落且伴腰膝酸软、头晕耳鸣等症者多属肾虚，伴头皮油热、瘙痒、心烦者多属血热。精血不足见发黄干枯、缓慢稀疏易落；血虚受风见突发圆形斑秃、光亮无恙；疳积病为小儿疳证发稀；先天遗传自幼即见。青壮年脱发而兼伴见症，责之肾虚或血热"},{"q":"肺胃热盛的咽喉多表现为","o":["咽喉红赤肿痛","咽喉色红，肿痛不显","咽部色淡红，漫肿","咽喉淡红，不肿不痛","咽喉色淡白溃腐"],"a":0,"e":"肺胃热盛，火热之邪上灼咽喉、气血壅滞，故咽喉红赤、肿胀明显、灼热疼痛、吞咽不利。咽喉色红而肿痛不显为肺肾阴虚、虚火上炎；咽部淡红漫肿为痰湿凝聚；淡红不肿不痛多属虚证或正常；色淡白溃腐为虚寒或疳证。红赤肿痛是实热壅滞咽喉之象"},{"q":"痰湿凝聚的咽喉多表现为","o":["咽喉红赤肿痛","咽喉色红，肿痛不显","咽部色淡红，漫肿","咽喉淡红，不肿不痛","咽喉色淡白溃腐"],"a":2,"e":"痰湿凝聚咽喉、气机不利、津液不布，故咽部色淡红、漫肿而外不红赤灼痛，常有咽中梗梗之感。咽喉红赤肿痛为肺胃热盛；色红而肿痛不显为肺肾阴虚；淡红不肿不痛多虚证；色淡白溃腐为虚寒湿腐。漫肿色淡是痰湿凝聚之象，与实热之红肿灼热恰成对照"},{"q":"肺肾阴虚的咽喉多表现为","o":["咽喉红赤肿痛","咽喉色红，肿痛不显","咽部色淡红，漫肿","咽喉淡红，不肿不痛","咽喉色淡白溃腐"],"a":1,"e":"肺肾阴虚，虚火循经上炎、津液不能上润，故咽喉色红但肿胀与疼痛不著，常伴咽干、午后或入夜加重。咽喉红赤肿痛明显为肺胃实热；淡红漫肿为痰湿凝聚；淡红不肿不痛为虚证；色淡白溃腐为虚寒。色红而肿痛不显是阴虚火旺咽喉的特点"},{"q":"食滞则","o":["干呕无物","呕吐酸腐","呕吐清水","喷射呕吐","朝食暮吐"],"a":1,"e":"食滞胃脘，宿食腐化、胃气上逆，故呕吐物酸腐、嗳腐吞酸、脘腹胀满、厌食，吐后反快。干呕无物为胃阴虚或胃气上逆；呕吐清水多为寒饮停胃；喷射呕吐多见于颅脑病变或热闭；朝食暮吐为反胃胃阳虚。酸腐气味是食滞呕吐的典型标志"},{"q":"反胃则","o":["干呕无物","呕吐酸腐","呕吐清水","喷射呕吐","朝食暮吐"],"a":4,"e":"反胃因胃阳虚衰、腐熟无权，食入不化、停留胃中，故朝食暮吐、暮食朝吐、吐出完谷不化、脘腹冷痛。呕吐酸腐为食滞内停；干呕无物为胃阴虚；呕吐清水为寒饮停胃；喷射呕吐多属颅脑病变。朝食暮吐、宿食不化是反胃区别于诸呕吐的特征"},{"q":"胃阴虚则","o":["干呕无物","呕吐酸腐","呕吐清水","喷射呕吐","朝食暮吐"],"a":0,"e":"胃阴虚，胃失濡润、和降失常，胃气上逆而无物可吐，故干呕、呃逆、口干咽燥、舌红少苔、脉细数。呕吐酸腐为食滞；朝食暮吐为反胃胃阳虚；呕吐清水为寒饮停胃；喷射呕吐多属颅脑病变。干呕无津、欲吐无物是胃阴虚的标志"},{"q":"“直中”是指","o":["两经或三经证候同时出现","一经证候已罢，继而出现另一经证候","互为表里的阴阳两经相传","一经证候未罢，又出现另一经证候","外邪入犯三阴而出现三阴证候"],"a":4,"e":"直中指外邪不经过三阳经传变，直接侵入三阴经而出现三阴证候，多因正气亏虚、邪气直入，病势较重。两经或三经证候同时出现是合病；一经证候已罢、继见另一经是传经；互为表里的阴阳两经证候同时出现是并病；一经证候未罢又见另一经亦属并病范畴，均与外邪直犯三阴的直中不同"},{"q":"“合病”是指","o":["两经或三经证候同时出现","一经证候已罢，继而出现另一经证候","互为表里的阴阳两经相传","一经证候未罢，又出现另一经证候","外邪入犯三阴而出现三阴证候"],"a":0,"e":"合病指伤寒两经或三经证候同时出现、同时发病，如太阳阳明合病。一经证候已罢、继而出现另一经证候为传经；一经未罢又见另一经证候为并病；互为表里的阴阳两经相传为表里传；外邪直犯三阴为直中。合病强调两经三经证候同时并见"},{"q":"“并病”是指","o":["两经或三经证候同时出现","一经证候已罢，继而出现另一经证候","互为表里的阴阳两经相传","一经证候未罢，又出现另一经证候","外邪入犯三阴而出现三阴证候"],"a":3,"e":"并病指一经证候未罢、又出现另一经证候，两经证候重叠并见，如太阳病未解又见阳明病。两经或三经证候同时出现为合病；一经已罢继见他经为传经；互为表里阴阳两经相传为表里传；外邪直犯三阴为直中。并病强调前经未罢、后经又起，与合病之同时发病不同"},{"q":"发作之前，咳嗽喷嚏，鼻流清涕，眼泪汪汪，耳后有红丝出现者","o":["风疹","湿疹","麻疹","瘾疹","痱子"],"a":2,"e":"麻疹前驱期见咳嗽、喷嚏、流清涕、流泪畏光，耳后发际可现红丝，继则按顺序遍身透发疹点、疹退脱屑留色素沉着。风疹疹点细小稀疏、消退快、无色素沉着；湿疹为多形性皮疹、渗出瘙痒；瘾疹为时隐时现风团；痱子为暑天汗疹。卡他症状加耳后红丝是麻疹先兆"},{"q":"其症肤痒，搔之则起连片大丘疹，或如云片，高起于皮肤，时隐时现者","o":["风疹","湿疹","麻疹","瘾疹","痱子"],"a":3,"e":"瘾疹即荨麻疹，以皮肤瘙痒、搔后起连片大丘疹或云片状风团、高起皮面、时隐时现、消退无痕为特点，多因气血不足、风邪外客。风疹疹细稀疏、伴低热；麻疹有前驱卡他症及麻疹黏膜斑；湿疹多形性皮疹、渗出结痂；痱子为暑季针尖样汗疹。时隐时现的风团是瘾疹特征"},{"q":"初起多为红斑，迅速形成肿胀、丘疹或水疱，继而水疱破裂、渗液，出现红色湿润之糜烂者","o":["风疹","湿疹","麻疹","瘾疹","痱子"],"a":1,"e":"湿疹由湿热蕴肤、禀赋不耐，皮疹多形，初起红斑，继见丘疹、水疱，破溃渗液，呈红色湿润糜烂、瘙痒剧烈、反复发作。瘾疹为时隐时现风团、无水疱渗液；风疹疹细稀疏；麻疹有前驱症与顺序透疹；痱子为暑季汗疹。多形性皮疹加渗出糜烂是湿疹特点"},{"q":"梭状指的病机多属","o":["湿热郁阻，气血不畅","心肺气虚，血瘀痰阻","寒湿内侵，络脉血瘀","脾肾虚弱，发育不良","风湿久蕴，痰瘀结聚"],"a":4,"e":"梭状指为近端指关节梭形肿胀、屈伸不利，因痹证日久、风湿之邪久蕴、痰瘀互结于关节筋脉。湿热郁阻、气血不畅多见关节红肿热痛；寒湿内侵、络脉血瘀见冷痛固定、遇寒加重；寒凝与痰瘀有别；心肺气虚、血瘀痰阻是杵状指病机；脾肾虚弱、发育不良是足内翻病机"},{"q":"杵状指的病机多属","o":["湿热郁阻，气血不畅","心肺气虚，血瘀痰阻","寒湿内侵，络脉血瘀","脾肾虚弱，发育不良","风湿久蕴，痰瘀结聚"],"a":1,"e":"杵状指为指趾末端膨大如鼓槌、甲床隆起，多见于久病心肺疾患，因心肺气虚、血行瘀滞、痰浊内阻、肢端失养所致。风湿久蕴、痰瘀结聚是梭状指病机；寒湿内侵、络脉血瘀见关节冷痛固定；脾肾虚弱、发育不良是足内翻；湿热郁阻见关节红肿热痛。杵状指以指端膨大、关联心肺久病为要"},{"q":"足内翻的病机多属","o":["湿热郁阻，气血不畅","心肺气虚，血瘀痰阻","寒湿内侵，络脉血瘀","脾肾虚弱，发育不良","风湿久蕴，痰瘀结聚"],"a":3,"e":"足内翻多为先天禀赋不足、脾肾虚弱、筋骨发育不良所致，足底向内翻转、行走不利，常自幼即见。风湿久蕴、痰瘀结聚是梭状指病机；心肺气虚、血瘀痰阻是杵状指病机；湿热郁阻、气血不畅见关节红肿热痛；寒湿内侵、络脉血瘀见冷痛固定。足内翻责之先天发育失常"},{"q":"邪闭、痛极、厥证等常见","o":["散脉","虚脉","长脉","疾脉","伏脉"],"a":4,"e":"伏脉须重按推筋着骨始得、脉位深沉伏而不显，主邪气内伏、痛极、厥证，因邪闭深重、气血郁遏不行。散脉浮散无根、至数不齐，主元气离散；虚脉举按皆无力；长脉首尾端长、超过寸尺，主阳气有余；疾脉一息七八至、主阳极阴竭。伏脉以脉位深沉难寻为要"},{"q":"亢而无制，真阴垂绝，常见","o":["散脉","虚脉","长脉","疾脉","伏脉"],"a":3,"e":"疾脉一息七八至、快于数脉，主阳极阴竭、真阴垂绝、元气将脱，为阳气亢极无制、阴液将亡之危象。散脉浮散无根、主元气离散；虚脉三部无力主虚；长脉形体长大、主阳盛；伏脉深沉不见、主邪闭。亢而无制、真阴垂绝是疾脉主病，与数脉仅主热象有别"},{"q":"元气耗散，病情危重，常见","o":["散脉","虚脉","长脉","疾脉","伏脉"],"a":0,"e":"散脉浮散无根、至数不齐、按之渐无而散漫不收，主元气耗散、病情危重、脏腑之气将绝。伏脉深沉需重按推寻、主邪闭痛极；虚脉无力但脉形不散乱；长脉形体长大超过本位；疾脉快而有序。散脉以浮散无根、节律不齐示危候，与虚脉之柔和但有序不同"},{"q":"肝郁化火多见","o":["洪数脉","弦数脉","浮数脉","滑数脉","细数脉"],"a":1,"e":"弦脉主肝胆郁滞，数脉主热，弦数并见为肝郁气滞、日久化火，见急躁易怒、口苦、胁痛、脉弦数有力。洪数脉主气分实热；浮数脉主风热表证；滑数脉主痰热、食积化热；细数脉主阴虚内热。弦脉示病在肝，故肝郁化火责之弦数，与洪数之里热蒸腾不同"},{"q":"气分实热多见","o":["洪数脉","弦数脉","浮数脉","滑数脉","细数脉"],"a":0,"e":"洪脉脉体宽大、来盛去衰，数脉主热，洪数并见为气分实热、里热蒸腾，见壮热、大汗、烦渴、脉洪大有力。弦数脉主肝郁化火；浮数脉主风热表证；滑数脉主痰热食积；细数脉主阴虚火旺。洪脉形大而来盛去衰是气分热盛的特征脉，与细数之阴虚内热迥异"},{"q":"食积化热多见","o":["洪数脉","弦数脉","浮数脉","滑数脉","细数脉"],"a":3,"e":"滑脉主痰食、数脉主热，滑数并见为食积化热或痰热内蕴，见脘腹胀满、嗳腐吞酸、便干尿黄、苔黄腻。洪数脉主气分实热；弦数脉主肝郁化火；浮数脉主风热表证；细数脉主阴虚内热。滑脉如盘走珠、主食积，故食积化热责之滑数"},{"q":"下焦湿热表现为","o":["大便溏泄而腥","大便溏泄腐臭","大便臭如败卵","小便黄浊臊臭","尿甜有苹果味"],"a":3,"e":"下焦湿热，湿热下注膀胱、气化不利，故小便短黄、浑浊臊臭，常伴尿频尿急、尿道灼热。大便溏泄而腥为脾胃虚寒；大便溏泄腐臭为大肠湿热；大便臭如败卵为宿食停滞；尿甜有苹果味为消渴重症酮症。黄浊臊臭是下焦湿热下注膀胱的特征"},{"q":"宿食停滞表现为","o":["大便溏泄而腥","大便溏泄腐臭","大便臭如败卵","小便黄浊臊臭","尿甜有苹果味"],"a":2,"e":"宿食停滞胃肠、腐化下行，故大便酸臭如败卵、夹有不消化食物，伴腹胀、嗳腐吞酸、腹痛即泻。大便溏泄而腥为脾胃虚寒；大便溏泄腐臭为湿热下注大肠；小便黄浊臊臭为下焦湿热；尿甜苹果味为消渴。败卵样酸臭味是食积停滞的标志"},{"q":"脾胃虚寒表现为","o":["大便溏泄而腥","大便溏泄腐臭","大便臭如败卵","小便黄浊臊臭","尿甜有苹果味"],"a":0,"e":"脾胃虚寒，运化失职、寒湿下注大肠，故大便清稀溏泄、气味腥淡，伴腹中冷痛、喜温喜按、四肢不温。大便溏泄腐臭为大肠湿热；臭如败卵为宿食停滞；小便黄浊臊臭为下焦湿热；尿甜苹果味为消渴。腥淡清稀是虚寒泄泻的特点，与湿热腐臭相对"},{"q":"虫积","o":["心下按之硬而痛","心下满，按之柔软无压痛","肿块按之坚硬，推之不移，痛有定处","肿块推之可移动，或痛无定处，聚散不定","腹内结块，按之手下如蚯蚓蠕动，或起伏聚散，往来不定"],"a":4,"e":"虫积腹内，蛔虫等聚散蠕动无常，故腹内结块、按之手下如蚯蚓蠕动、起伏聚散、往来不定，常伴面黄消瘦、脐周腹痛。心下按之硬而痛为结胸；心下满、按之柔软无压痛为痞证；癥积坚硬、推之不移、痛有定处；瘕聚推之可移、聚散不定。蚯蚓状蠕动感是虫积特征"},{"q":"癥积","o":["心下按之硬而痛","心下满，按之柔软无压痛","肿块按之坚硬，推之不移，痛有定处","肿块推之可移动，或痛无定处，聚散不定","腹内结块，按之手下如蚯蚓蠕动，或起伏聚散，往来不定"],"a":2,"e":"癥属血分，瘀血内停、结块有形，故肿块坚硬、推之不移、痛有定处，病在血分而固定难散。瘕聚属气分，块推之可移、痛无定处、聚散无常；虫积按之如蚯蚓蠕动、起伏不定；心下按之硬而痛为结胸；心下满软而无压痛为痞证。癥积固定不移是血瘀特征"},{"q":"瘕聚","o":["心下按之硬而痛","心下满，按之柔软无压痛","肿块按之坚硬，推之不移，痛有定处","肿块推之可移动，或痛无定处，聚散不定","腹内结块，按之手下如蚯蚓蠕动，或起伏聚散，往来不定"],"a":3,"e":"瘕属气分，气机郁滞、聚散无常，故肿块推之可移动、痛无定处、时聚时散，病在气分而无定形。癥积属血分，坚硬不移、痛有定处；虫积按之如蚯蚓蠕动、起伏聚散；心下按之硬而痛为结胸；心下满软不痛为痞证。瘕聚移而无形是气滞特征，与癥积之固定不移相对"},{"q":"金实不鸣可见","o":["语声重浊","音哑或失音","呻吟","惊呼","狂言"],"a":1,"e":"金实不鸣因外邪犯肺、肺气壅闭，肺窍不利而卒然音哑失音，起病急、属实证，常伴咳嗽、咽痛、苔薄黄。语声重浊多因外感风寒或湿邪束肺；呻吟为痛楚之声；惊呼多属惊恐或小儿惊风；狂言为痰火扰心之妄语。金实不鸣与金破不鸣虽均失音，本证以邪实壅肺、起病急骤为别"},{"q":"金破不鸣可见","o":["语声重浊","音哑或失音","呻吟","惊呼","狂言"],"a":1,"e":"金破不鸣因肺肾阴虚、虚火上炎、肺气不足，咽喉失润而声音嘶哑或失音，起病缓慢、日久渐致、属虚证，伴咽干、潮热盗汗、舌红少苔。语声重浊为外感风寒湿邪；呻吟主痛；惊呼主惊恐惊风；狂言为痰火扰心。金破不鸣与金实不鸣同为失音，本证以肺肾阴虚、起病缓为要"},{"q":"津枯肺损可见","o":["语声重浊","音哑或失音","呻吟","惊呼","狂言"],"a":1,"e":"津枯肺损，肺阴亏虚、津液不能上润咽喉、声道失养，故音哑失音、咽干口燥、干咳少痰，日久渐成。语声重浊为风寒湿邪束肺；呻吟主痛苦；惊呼主惊恐或惊风；狂言为痰火扰心之妄言。津枯肺损属阴虚津伤之失音，与外邪壅肺之金实不鸣虚实迥异"},{"q":"脘腹痞闷，纳呆呕恶，便溏不爽，身热不扬，苔黄腻，宜诊断为","o":["肝脾不调证","湿热蕴脾证","肝火炽盛证","肝胃不和证","肝经湿热证"],"a":1,"e":"湿热蕴脾证因湿热蕴结脾胃、运化受阻，故脘腹痞闷、纳呆呕恶、便溏不爽、身热不扬、苔黄腻、脉濡数。肝脾不调见胸胁胀痛、肠鸣矢气、脉弦；肝胃不和见胃脘胀痛、嗳气吞酸；肝火炽盛见口苦目赤、便秘尿黄；肝经湿热见带下黄臭、外阴瘙痒。湿热困脾、运化失常是本证关键"},{"q":"纳呆腹胀，便溏不爽，肠鸣矢气，胸胁胀满窜痛，易怒，脉弦，宜诊断为","o":["肝脾不调证","湿热蕴脾证","肝火炽盛证","肝胃不和证","肝经湿热证"],"a":0,"e":"肝脾不调证因肝气郁结、横逆犯脾、脾失健运，故纳呆腹胀、便溏不爽、肠鸣矢气，兼胸胁胀满窜痛、易怒、脉弦。湿热蕴脾见身热不扬、苔黄腻、无胁痛；肝胃不和病在胃，见胃脘胀痛、嗳气；肝火炽盛见目赤口苦、便秘实热；肝经湿热见带下黄臭、阴痒。肝郁与脾虚并见是本证要点"},{"q":"带下色黄臭秽，外阴瘙痒，尿黄，舌红苔黄腻，脉弦数，宜诊断为","o":["肝脾不调证","湿热蕴脾证","肝火炽盛证","肝胃不和证","肝经湿热证"],"a":4,"e":"肝经湿热证因湿热循肝经下注，故带下色黄臭秽、外阴瘙痒、尿黄、舌红苔黄腻、脉弦数。湿热蕴脾以脘腹痞闷、纳呆便溏为主，无阴部症状；肝脾不调见胸胁胀痛、便溏、脉弦；肝胃不和见胃脘胀痛、嗳气吞酸；肝火炽盛见目赤口苦、便秘尿黄。湿热循经下注阴部是本证特点"},{"q":"上焦病证的病位是在","o":["肺与大肠","肝胆脾胃","肺与心包","脾与胃","肝与肾"],"a":2,"e":"三焦辨证中上焦包括肺与心包，温病初起邪犯上焦，肺卫失宣则发热、微恶寒、咳嗽，逆传心包则神昏谵语、舌绛。脾与胃属中焦病位；肝与肾属下焦病位；肺与大肠虽为表里，但非上焦病位划分；肝胆脾胃分属中下焦。上焦病位当定在肺与心包"},{"q":"中焦病证的病位是在","o":["肺与大肠","肝胆脾胃","肺与心包","脾与胃","肝与肾"],"a":3,"e":"中焦病证病位在脾胃，温病邪入中焦、脾胃受病，见身热不扬、脘腹痞满、纳呆、大便燥结或溏泄、苔黄腻。肺与心包属上焦病位；肝与肾属下焦病位；肺与大肠非中焦划分；肝胆脾胃之中肝不属中焦病位。中焦以脾胃受邪、运化失常为病位核心"},{"q":"下焦病证的病位是在","o":["肺与大肠","肝胆脾胃","肺与心包","脾与胃","肝与肾"],"a":4,"e":"下焦病证病位在肝肾，温病后期邪入下焦、耗伤肝肾之阴，见身热、手足心热、口燥咽干、耳聋、神疲、舌绛少苔、脉细数。肺与心包属上焦；脾与胃属中焦；肺与大肠、肝胆脾胃均非下焦病位划分。下焦病位当定在肝肾，以肝肾阴虚、虚风内动为常见"},{"q":"脾虚、湿证常见的面色是","o":["白色","黄色","赤色","黑色","青色"],"a":1,"e":"黄色主脾虚、湿证，脾虚运化失职、水湿内停，气血不能上荣，故面色萎黄或黄胖虚浮、形体困重。白色主虚寒、失血；赤色主热证、戴阳；黑色主肾虚、水饮、剧痛；青色主寒证、瘀血、惊风。黄为脾之色，脾虚湿盛则面色发黄，萎黄多血虚、黄胖多湿"},{"q":"寒证、瘀血、惊风常见的面色是","o":["白色","黄色","赤色","黑色","青色"],"a":4,"e":"青色主寒证、痛证、瘀血、惊风，寒凝血滞、经脉拘急、气血不通，故面色发青，小儿惊风常见眉间鼻柱青紫。黄色主脾虚湿证；赤色主热；白色主虚寒失血；黑色主肾虚水饮剧痛。青色以寒凝、瘀阻、惊风为多见，与赤色主热、黄色主湿各有所主"},{"q":"肾虚、水饮、剧痛常见的面色是","o":["白色","黄色","赤色","黑色","青色"],"a":3,"e":"黑色主肾虚、水饮、瘀血、剧痛，肾阳虚衰、水寒上泛、血行瘀滞，故面色黧黑或晦暗如漆。黄色主脾虚湿证；青色主寒、瘀、惊风；赤色主热；白色主虚寒失血。黑为肾之色，肾虚水饮上泛、剧痛见面色黑，与白色之虚寒失血不同"},{"q":"燥邪犯肺证与肺阴虚证共见的表现是","o":["恶寒发热","干咳痰少","潮热盗汗","舌苔黄腻","痰白清稀"],"a":1,"e":"燥邪犯肺与肺阴虚均致肺失濡润、肺气上逆，故共见干咳、痰少而黏、咽干口燥，此为两证肺系同有之象。恶寒发热仅燥邪犯肺外感所有；潮热盗汗为肺阴虚内热；舌苔黄腻主湿热，二者皆非；痰白清稀属寒痰。干咳少痰是两证共有表现，鉴别重在表里与兼症"},{"q":"燥邪犯肺证可兼见","o":["恶寒发热","干咳痰少","潮热盗汗","舌苔黄腻","痰白清稀"],"a":0,"e":"燥邪犯肺为外感，燥邪犯肺卫、卫表失和，故可兼见恶寒发热、头痛、鼻塞等表证，起病较急。干咳痰少是两证共有而非燥邪独有；潮热盗汗为肺阴虚；舌苔黄腻主湿热；痰白清稀属寒痰。有无恶寒发热等表证，是燥邪犯肺外感与肺阴虚内伤的鉴别要点"},{"q":"肺阴虚证可兼见","o":["恶寒发热","干咳痰少","潮热盗汗","舌苔黄腻","痰白清稀"],"a":2,"e":"肺阴虚证因阴液亏虚、虚热内生、肺络受损，故可兼见潮热、盗汗、五心烦热、颧红、舌红少苔、脉细数。恶寒发热为外感表证，肺阴虚无之；干咳痰少是两证共有；舌苔黄腻主湿热；痰白清稀属寒痰。潮热盗汗是阴虚内热的标志，与外感燥邪之表证相对"},{"q":"极细而软，若有若无，按之欲绝的脉象是","o":["虚脉","紧脉","微脉","弱脉","濡脉"],"a":2,"e":"微脉极细极软、若有若无、按之欲绝、至数模糊，主气血大虚、阳气衰微、病情危重。弱脉沉细而极软、按之仍可得；濡脉浮而细软；虚脉举按皆无力、脉体空豁但形不若此细极；紧脉紧张有力如切绳。微脉以细软至极、似有似无为特征，较虚脉更为微弱"},{"q":"极软而沉细的脉象是","o":["虚脉","紧脉","微脉","弱脉","濡脉"],"a":3,"e":"弱脉极软而沉细、须重按始得、按之无力，主气血不足、阳气虚衰，脉体细小与柔软并见、部位偏沉。微脉更细软、若有若无、按之欲绝；濡脉浮而细软、位在浮分；虚脉三部皆无力但不专沉细；紧脉紧张有力。弱脉以沉细极软为要，与濡脉一沉一浮恰成对照"},{"q":"浮而细软无力的脉象是","o":["虚脉","紧脉","微脉","弱脉","濡脉"],"a":4,"e":"濡脉浮而细软无力、轻按即得、重按反减，主虚证、湿证，因气血不足、湿邪阻遏、脉气不充。弱脉沉细极软、须重按方得；微脉极细软、若有若无；虚脉举按皆无力、脉体空豁宽大；紧脉紧张有力如切绳。濡脉以浮细软为特征，与弱脉之沉细形成浮沉对照"},{"q":"饮停胁下的主症是","o":["胸胁饱满，支撑胀痛","咳嗽，痰稀色白，喉中哮鸣","胸闷心悸，虚里搏动不显","脘腹水声辘辘，呕吐清水","四肢浮肿，身体困重"],"a":0,"e":"饮停胁下即悬饮，饮邪停积胸胁、气机阻滞、络脉不和，故胸胁饱满、支撑胀痛、咳唾引痛、转侧不利。咳嗽痰稀、喉中哮鸣为饮停于肺；胸闷心悸、虚里搏动不显为饮停胸膈之支饮；脘腹水声辘辘、呕吐清水为饮停胃肠；四肢浮肿困重为溢饮"},{"q":"饮停胃肠的主症是","o":["胸胁饱满，支撑胀痛","咳嗽，痰稀色白，喉中哮鸣","胸闷心悸，虚里搏动不显","脘腹水声辘辘，呕吐清水","四肢浮肿，身体困重"],"a":3,"e":"饮停胃肠即痰饮，胃失和降、水饮内停，故脘腹痞胀、水声辘辘、泛吐清水、纳呆。胸胁饱满、支撑胀痛为饮停胁下之悬饮；咳嗽痰稀、喉中哮鸣为饮停于肺；胸闷心悸、虚里搏动不显为饮停胸膈；四肢浮肿、身体困重为溢饮。胃肠振水声、吐清水是痰饮特征"},{"q":"饮停于胸膈的主症是","o":["胸胁饱满，支撑胀痛","咳嗽，痰稀色白，喉中哮鸣","胸闷心悸，虚里搏动不显","脘腹水声辘辘，呕吐清水","四肢浮肿，身体困重"],"a":2,"e":"饮停胸膈即支饮，饮邪上逆、心阳受遏、肺气不利，故胸闷、心悸、虚里搏动不显、息促不得卧。胸胁饱满、支撑胀痛为饮停胁下之悬饮；咳嗽痰稀、喉中哮鸣为饮停于肺；脘腹水声辘辘、呕吐清水为饮停胃肠；四肢浮肿、身体困重为溢饮。支饮病位在胸膈心肺"},{"q":"心悸怔忡，心胸胀痛，伴胁胀，善太息，舌淡红，脉象弦。证属","o":["气滞心脉证","寒凝心脉证","心阳暴脱证","瘀阻心脉证","痰阻心脉证"],"a":0,"e":"气滞心脉证因气机郁滞、心脉不畅，故心悸怔忡、心胸胀痛、痛连胁肋、善太息、舌淡红、脉弦，胀痛走窜是气滞特征。寒凝心脉见突然剧痛、形寒肢冷、脉沉紧；瘀阻心脉见刺痛固定、唇舌青紫、脉涩结代；痰阻心脉见心胸闷痛、体胖苔腻、脉滑；心阳暴脱见大汗肢冷、脉微欲绝"},{"q":"心悸怔忡，突起心胸剧痛，形寒肢冷，舌淡苔白，脉沉紧。证属","o":["气滞心脉证","寒凝心脉证","心阳暴脱证","瘀阻心脉证","痰阻心脉证"],"a":1,"e":"寒凝心脉证因寒邪内侵、心脉拘急收引、气血不通，故心悸怔忡、突起心胸剧痛、形寒肢冷、舌淡苔白、脉沉紧。气滞心脉见胀痛、善太息、脉弦；瘀阻心脉见刺痛固定、唇舌青紫、脉涩；痰阻心脉见闷痛、苔腻脉滑；心阳暴脱见冷汗淋漓、四肢厥冷、脉微。沉紧脉与暴作剧痛是寒凝特征"},{"q":"心悸怔忡，心胸刺痛，唇舌青紫，脉象涩或结代。证属","o":["气滞心脉证","寒凝心脉证","心阳暴脱证","瘀阻心脉证","痰阻心脉证"],"a":3,"e":"瘀阻心脉证因瘀血痹阻心脉、血行不畅、不通则痛，故心悸怔忡、心胸刺痛、痛处固定、唇舌青紫、脉涩或结代。气滞心脉见胀痛走窜、脉弦；寒凝心脉见剧痛、形寒、脉沉紧；痰阻心脉见胸闷痛、苔腻脉滑；心阳暴脱见大汗、脉微欲绝。刺痛青紫、涩脉结代是瘀阻特征"},{"q":"痰火扰心为","o":["夺气","郑声","独语","错语","狂言"],"a":4,"e":"狂言为痰火扰心、神明被扰，痰火壅盛、心神狂乱，故见狂言乱语、妄言妄见、躁动不安、面赤气粗，属阳证实证。夺气为语声低微、气短不续，属中气大虚；郑声为神昏而语言重复、声音低弱，属心气大伤；独语为自言自语、见人便止；错语为语言错乱、说后自知。狂言躁妄是痰火扰心之象"},{"q":"中气大虚为","o":["夺气","郑声","独语","错语","狂言"],"a":0,"e":"夺气指语声低微、气短不足以息、言语断续无力、欲言不能接续，为中气大虚、宗气不足、肺气衰少所致。郑声为神志不清、语言重复低弱，属心气大伤；独语为清醒时自言自语、见人便止，多心气不足夹痰；错语为语言错乱而说后自知；狂言为痰火扰心的躁妄之言。夺气以气短声低、欲续不能为特征"},{"q":"心气大伤为","o":["夺气","郑声","独语","错语","狂言"],"a":1,"e":"郑声为神志不清、语言重复、声音低弱模糊、喃喃不休，是心气大伤、精神散乱之象，多见于久病危重、正气将脱。夺气为语声低微、气短不续，属中气大虚；独语为自言自语、见人便止，多心气不足夹痰；错语为语言错乱、说后能自知；狂言为痰火扰心。郑声以神昏、重复低弱为要点"},{"q":"“寸口候脏腑”中左寸候","o":["肝胆","肺（统括胸以上至头部）、大肠","心、小肠","脾胃（统括膈以下至脐上）","肾（统括脐以下至足部）、膀胱"],"a":2,"e":"寸口分候脏腑，左寸候心与小肠，反映心及小肠病变，如心悸、失眠、口舌生疮等上焦心系之疾。右寸候肺与大肠；左关候肝胆；右关候脾胃，统括膈以下至脐上；两尺候肾与膀胱，统括脐以下至足部。左寸候心小肠是寸口脏腑分候的固定定位"},{"q":"“寸口候脏腑”中右寸候","o":["肝胆","肺（统括胸以上至头部）、大肠","心、小肠","脾胃（统括膈以下至脐上）","肾（统括脐以下至足部）、膀胱"],"a":1,"e":"寸口分候脏腑，右寸候肺与大肠，肺主气司呼吸、上通鼻窍、外合皮毛，故候胸以上至头部及其相关病变。左寸候心与小肠；左关候肝胆；右关候脾胃，统括膈下至脐上；两尺候肾与膀胱，统括脐下至足部。右寸候肺与大肠是寸口脏腑分候的定位"},{"q":"“寸口候脏腑”中左关候","o":["肝胆","肺（统括胸以上至头部）、大肠","心、小肠","脾胃（统括膈以下至脐上）","肾（统括脐以下至足部）、膀胱"],"a":0,"e":"寸口分候脏腑，左关候肝胆，肝主疏泄、藏血，胆附于肝、主决断，故左关候肝胆，可测胁痛、目疾、情志等肝胆病变。左寸候心与小肠；右寸候肺与大肠；右关候脾胃，统括膈下至脐上；两尺候肾与膀胱，统括脐下至足部。左关候肝胆是寸口脏腑分候的固定配属"},{"q":"脘腹痞闷，纳呆呕恶，大便溏泄，头身困重，苔白腻，脉缓，宜诊断为","o":["脾胃阳虚证","寒湿困脾证","寒饮停胃证","寒滞胃肠证","脾肾阳虚证"],"a":1,"e":"寒湿困脾证因寒湿内侵、困遏脾阳、运化失司，故脘腹痞闷、纳呆呕恶、大便溏泄、头身困重、苔白腻、脉缓。脾胃阳虚见腹中冷痛、喜温喜按、四肢不温；寒饮停胃见呕吐清水、胃有振水声、脉沉弦；寒滞胃肠见冷痛剧烈、脉弦紧；脾肾阳虚见五更泄泻、腰膝酸冷。困重苔白腻是本证要点"},{"q":"五更泄泻，便质清冷，畏寒，面白神疲，舌淡，脉沉迟无力，宜诊断为","o":["脾胃阳虚证","寒湿困脾证","寒饮停胃证","寒滞胃肠证","脾肾阳虚证"],"a":4,"e":"脾肾阳虚证因脾肾阳虚、火不暖土、运化失职、大肠失固，故五更泄泻、便质清冷、畏寒、面白神疲、舌淡、脉沉迟无力。寒湿困脾见脘腹痞闷、头身困重、苔白腻；寒饮停胃见呕吐清水、胃中振水声；寒滞胃肠见冷痛、脉弦紧；脾胃阳虚以胃脘冷痛、喜温喜按为主。五更泄泻是脾肾阳虚标志"},{"q":"脘腹痞胀，呕吐清水，胃中有振水声，苔白滑，脉沉弦，宜诊断为","o":["脾胃阳虚证","寒湿困脾证","寒饮停胃证","寒滞胃肠证","脾肾阳虚证"],"a":2,"e":"寒饮停胃证因寒饮内停胃腑、胃失和降、气机上逆，故脘腹痞胀、呕吐清水、胃中有振水声、苔白滑、脉沉弦。寒湿困脾见头身困重、大便溏泄、苔白腻；脾胃阳虚见胃脘冷痛、喜温喜按；寒滞胃肠见冷痛、腹泻清稀、脉弦紧；脾肾阳虚见五更泄泻、腰膝酸冷。振水声、吐清水是寒饮停胃特征"},{"q":"胃脘、腹部冷痛，得温则减，恶心呕吐，腹泻清稀，苔白润，脉弦紧，宜诊断为","o":["脾胃阳虚证","寒湿困脾证","寒饮停胃证","寒滞胃肠证","脾肾阳虚证"],"a":3,"e":"寒滞胃肠证因寒邪直中胃肠、气机凝滞、传导失司，故胃脘腹部冷痛、得温则减、恶心呕吐、腹泻清稀、苔白润、脉弦紧。寒饮停胃见呕吐清水、振水声、痞胀；寒湿困脾见头身困重、纳呆、苔白腻；脾胃阳虚见冷痛喜按、病程较长；脾肾阳虚见五更泄泻、腰膝酸冷。弦紧脉、冷痛暴作是寒滞特征"},{"q":"表证夹痰多见","o":["弦滑脉","浮滑脉","洪数脉","沉涩脉","沉迟脉"],"a":1,"e":"浮脉主表、滑脉主痰，浮滑并见为外感表证夹痰或风痰，故表证夹痰多见浮滑脉，常伴咳嗽痰多、恶寒发热。弦滑脉主痰饮、肝火夹痰，病在里；洪数脉主气分实热；沉涩脉主寒凝血瘀；沉迟脉主里寒。浮滑之浮提示病位在表，与里痰内停之弦滑不同"},{"q":"寒凝血瘀多见","o":["弦滑脉","浮滑脉","洪数脉","沉涩脉","沉迟脉"],"a":3,"e":"沉脉主里、涩脉主血行不畅，沉涩并见为寒凝血瘀、气血运行受阻、不通则痛，见疼痛固定、面色晦暗、舌暗。浮滑脉主表证夹痰；弦滑脉主痰饮、肝火夹痰；洪数脉主气分实热；沉迟脉主里寒，但迟脉只主寒而不主瘀。涩脉如轻刀刮竹、主瘀血，沉涩提示里寒兼血瘀"},{"q":"里寒证多见","o":["弦滑脉","浮滑脉","洪数脉","沉涩脉","沉迟脉"],"a":4,"e":"沉脉主里、迟脉主寒，沉迟并见为里寒证、阳气不足、阴寒内盛，一息不足四至，伴畏寒肢冷、腹痛喜温。浮滑脉主表证夹痰；弦滑脉主痰饮；洪数脉主气分实热；沉涩脉主寒凝血瘀，兼见涩象。沉迟以脉率缓慢且部位深沉为里寒特征，与沉涩之主瘀不同"},{"q":"温病热郁肺胃的临床表现是","o":["心烦懊恼，坐卧不安，身热，舌苔黄，脉数","身热，口苦而渴，干呕心烦，苔黄，脉弦数","心烦汗出，身热喘咳，渴欲饮冷，舌苔黄燥","身热，心烦不寐，斑疹隐隐，舌绛，脉细有力","便秘潮热，腹部胀满硬痛，苔黄燥，脉沉有力"],"a":2,"e":"温病热郁肺胃，热邪壅肺则身热喘咳、汗出，热盛伤津则渴欲饮冷、舌苔黄燥、心烦，是邪热在气分肺胃之象。心烦懊恼、坐卧不安为热扰胸膈；身热口苦、干呕心烦、脉弦数为热郁胆经；心烦不寐、斑疹隐隐、舌绛为热入营分；便秘潮热、腹满硬痛为阳明腑实。喘咳苔燥是热郁肺胃之据"},{"q":"温病热扰胸膈的临床表现是","o":["心烦懊恼，坐卧不安，身热，舌苔黄，脉数","身热，口苦而渴，干呕心烦，苔黄，脉弦数","心烦汗出，身热喘咳，渴欲饮冷，舌苔黄燥","身热，心烦不寐，斑疹隐隐，舌绛，脉细有力","便秘潮热，腹部胀满硬痛，苔黄燥，脉沉有力"],"a":0,"e":"热扰胸膈，郁热留扰胸膈、心神不宁，故心烦懊恼、坐卧不安、身热、舌苔黄、脉数，即栀子豉汤证，无形邪热郁而不宣。热郁肺胃见喘咳、汗出、渴饮、苔燥；热郁胆经见口苦、干呕、脉弦数；热入营分见斑疹隐隐、舌绛、脉细数；阳明腑实见便秘潮热、腹满硬痛。懊恼难名是热扰胸膈特征"},{"q":"温病热郁胆经的临床表现是","o":["心烦懊恼，坐卧不安，身热，舌苔黄，脉数","身热，口苦而渴，干呕心烦，苔黄，脉弦数","心烦汗出，身热喘咳，渴欲饮冷，舌苔黄燥","身热，心烦不寐，斑疹隐隐，舌绛，脉细有力","便秘潮热，腹部胀满硬痛，苔黄燥，脉沉有力"],"a":1,"e":"热郁胆经，少阳枢机不利、胆火上炎、胆气犯胃，故身热、口苦而渴、干呕心烦、苔黄、脉弦数，即蒿芩清胆汤证。热扰胸膈见心烦懊恼、坐卧不安；热郁肺胃见喘咳汗出、舌苔黄燥；热入营分见心烦不寐、斑疹隐隐、舌绛；阳明腑实见便秘潮热、腹满硬痛。口苦脉弦数是胆经郁热之征"},{"q":"肢体浮肿，脘腹痞满，泛恶欲呕，面色晦暗，舌苔白腻。宜诊断为","o":["脾阳虚证","风水相搏证","脾肾阳虚证","寒湿困脾证","肾虚水泛证"],"a":3,"e":"寒湿困脾，寒湿内侵、阳气被遏、水湿不化、泛溢肌肤，故肢体浮肿、脘腹痞满、泛恶欲呕、面色晦暗、舌苔白腻。脾阳虚见腹中冷痛、喜温喜按、四肢不温；风水相搏见头面眼睑先肿、发热恶风、脉浮数；脾肾阳虚见腰膝酸冷、五更泄泻；肾虚水泛见咳喘痰鸣、心悸气短、腰膝酸冷。晦暗苔腻是寒湿之象"},{"q":"头面眼睑先肿，继而全身浮肿，发热恶风，脉象浮数。宜诊断为","o":["脾阳虚证","风水相搏证","脾肾阳虚证","寒湿困脾证","肾虚水泛证"],"a":1,"e":"风水相搏，风邪外袭、肺失宣降、通调水道失职、水湿泛溢肌肤，故头面眼睑先肿、继而全身浮肿、发热恶风、脉浮数，起病较急。寒湿困脾见脘腹痞满、身重苔腻、肿势较缓；脾阳虚见腹中冷痛、四肢不温；脾肾阳虚见腰膝酸冷、五更泄泻；肾虚水泛见咳喘心悸、腰膝酸冷。头面先肿兼表证是风水特点"},{"q":"肢体浮肿，面白形寒，腰膝酸冷，咳喘痰鸣，心悸气短。宜诊断为","o":["脾阳虚证","风水相搏证","脾肾阳虚证","寒湿困脾证","肾虚水泛证"],"a":4,"e":"肾虚水泛，肾阳亏虚、气化失司、水液泛溢，上凌心肺，故肢体浮肿、面白形寒、腰膝酸冷、咳喘痰鸣、心悸气短、舌淡胖苔白滑。寒湿困脾见脘腹痞满、苔白腻、身重；风水相搏见头面先肿、发热恶风、脉浮数；脾阳虚见腹中冷痛、喜温喜按；脾肾阳虚见五更泄泻。腰膝酸冷加咳喘心悸是水气凌心之象"},{"q":"寒滞肝脉证属于","o":["实寒证","虚热证","虚寒证","实热证","湿热证"],"a":0,"e":"寒滞肝脉证为寒邪侵袭肝经、邪气壅盛而正气未虚，寒性收引凝滞、肝脉失和，故属实寒证，见少腹冷痛、牵引阴器、遇寒加重、脉沉弦。虚寒证为阳气不足、内生虚寒、病程较缓；实热证为热邪壅盛；虚热证为阴虚内热；湿热证为湿与热结、苔黄腻。寒滞肝脉起病急、寒邪偏盛，故属实寒"},{"q":"肝阴虚证属于","o":["实寒证","虚热证","虚寒证","实热证","湿热证"],"a":1,"e":"肝阴虚证为肝阴液亏虚、虚热内生、筋脉失养，故属虚热证，见头晕目涩、胁痛、视物昏花、潮热盗汗、五心烦热、舌红少苔、脉细数。实热证为肝火炽盛、邪热壅盛；实寒证为寒滞肝脉；虚寒证为阳气亏虚内寒；湿热证为肝胆湿热、苔黄腻。阴虚生内热，故肝阴虚归虚热，与肝火炽盛之实热相对"},{"q":"肝火炽盛证属于","o":["实寒证","虚热证","虚寒证","实热证","湿热证"],"a":3,"e":"肝火炽盛证为火热之邪壅盛于肝、正气未虚，肝火上炎、疏泄失常，故属实热证，见目赤肿痛、口苦、头痛急躁易怒、便秘尿黄、舌红苔黄、脉弦数有力。虚热证为肝阴虚内热；实寒证为寒滞肝脉；虚寒证为阳虚内寒；湿热证为肝胆湿热、苔黄腻。肝火炽盛来势急、热象充实，故属实热"},{"q":"阴虚肺燥的特点是","o":["干咳","咳声低微","咳声重浊","咳如犬吠","顿咳"],"a":0,"e":"阴虚肺燥，肺阴亏虚、虚燥内生、肺气上逆、气道失润，故干咳无痰或少痰、咽干口燥、舌红少苔，日久渐起。咳声低微为肺气虚；咳声重浊为外感风寒或痰湿阻肺；咳如犬吠为白喉疫毒攻喉；顿咳为百日咳。干咳少痰是阴虚肺燥特点，与外感咳嗽之重浊有声不同"},{"q":"白喉的特点是","o":["干咳","咳声低微","咳声重浊","咳如犬吠","顿咳"],"a":3,"e":"白喉为疫毒攻喉、喉间生出灰白色伪膜、不易擦去、气道受阻，故咳声如犬吠、声音嘶哑、吸气困难、咽痛，病情危重。干咳为阴虚肺燥；咳声低微为肺气虚；咳声重浊为风寒或痰湿阻肺；顿咳为百日咳之阵发痉挛性咳嗽。犬吠样咳伴喉间白膜是白喉特征，与虚燥干咳迥异"},{"q":"百日咳的特点是","o":["干咳","咳声低微","咳声重浊","咳如犬吠","顿咳"],"a":4,"e":"顿咳即百日咳，外邪犯肺、气道痉挛、痰浊阻肺，故见阵发性连声咳嗽、咳毕有鸡鸣样回声、日轻夜重、病程绵长，多见于小儿。干咳为阴虚肺燥；咳声低微为肺气虚；咳声重浊为风寒痰湿；咳如犬吠为白喉。阵发性痉挛性顿咳伴回声是百日咳特征，与一般咳嗽不同"},{"q":"阴液亏损，肝及所系组织器官失养，虚热内扰，以眩晕、目涩、胁痛及阴虚症状为主要表现的证为","o":["肝阳上亢证","热极生风证","阴虚风动证","血虚生风证","肝阴虚证"],"a":4,"e":"肝阴虚证为阴液亏损、肝及所系组织器官失养、虚热内扰，故见眩晕、目涩、胁痛、耳鸣，兼潮热盗汗、五心烦热、舌红少苔、脉细数。肝阳上亢以头目胀痛、面红烦躁、上盛下虚为主；阴虚风动以手足震颤蠕动等动风表现为主；血虚生风见肢体麻木震颤而血虚象明显；热极生风见高热抽搐。本证以阴虚失养为主"},{"q":"肝肾阴亏，阴不制阳，阳亢于上，以眩晕耳鸣，头目胀痛，面红烦躁，腰膝酸软等上盛下虚症状为主要表现的证为","o":["肝阳上亢证","热极生风证","阴虚风动证","血虚生风证","肝阴虚证"],"a":0,"e":"肝阳上亢证因肝肾阴亏、阴不制阳、肝阳亢逆于上，故见眩晕耳鸣、头目胀痛、面红烦躁、失眠多梦，兼腰膝酸软等下虚之象，属上盛下虚。肝阴虚以目涩胁痛、阴虚内热为主而无阳亢；阴虚风动以震颤蠕动为主；血虚生风见麻木震颤；热极生风见高热抽搐。上盛下虚是肝阳上亢特征"},{"q":"肝阴亏虚，筋脉失养，虚风内动，以手足震颤、蠕动，肢体抽搐，眩晕及阴虚症状为主要表现的证为","o":["肝阳上亢证","热极生风证","阴虚风动证","血虚生风证","肝阴虚证"],"a":2,"e":"阴虚风动证因肝阴亏虚、筋脉失养、虚风内动，故见手足震颤、蠕动、肢体抽搐，兼眩晕、潮热盗汗、五心烦热、舌红少苔、脉细数，起病较缓。肝阳上亢见头目胀痛、面红、上盛下虚；肝阴虚以失养内热为主而无动风；血虚生风见麻木拘急而血虚象著；热极生风见高热神昏抽搐。虚风蠕动、起病缓是阴虚风动特征"},{"q":"肺肾阴虚、气阴两虚可见","o":["项强","项软","颈脉怒张","扁平胸","桶状胸"],"a":3,"e":"扁平胸表现为胸廓扁平、前后径小于左右径之半、锁骨上窝凹陷，多见于肺肾阴虚、气阴两虚及体型瘦长者，伴颧红、盗汗、干咳。项强为颈项僵硬，多外感或惊风；项软为颈项软弱、抬头无力，属先天不足或气血虚；颈脉怒张为心肾阳衰、水气凌心；桶状胸为伏饮积痰、壅滞肺气"},{"q":"心肾阳衰、水气凌心可见","o":["项强","项软","颈脉怒张","扁平胸","桶状胸"],"a":2,"e":"心肾阳衰、水气凌心、血脉瘀滞，故见颈脉怒张、伴心悸气短、肢体浮肿、面白形寒、腰膝酸冷、咳喘痰鸣，是水饮上逆、心阳衰微之危象。扁平胸为肺肾阴虚、气阴两虚；项强多外感或惊风；项软为先天不足或气血虚；桶状胸为伏饮积痰、壅滞肺气。颈脉怒张是水气凌心之象"},{"q":"伏饮积痰，壅滞肺气可见","o":["项强","项软","颈脉怒张","扁平胸","桶状胸"],"a":4,"e":"伏饮积痰、壅滞肺气、肺气胀满不收，故胸廓呈桶状、前后径增大、肋间隙增宽、呼吸不畅，多见于肺胀、久咳喘证。扁平胸为肺肾阴虚、气阴两虚、体型瘦长；项强多外感惊风；项软为先天或气血不足；颈脉怒张为心肾阳衰、水气凌心。桶状胸以肺气壅滞胀满为病机"},{"q":"厥阴病证的临床表现是","o":["脉微细，但欲寐","身热，不恶寒反恶热，汗出，脉大","寒热往来，胸胁苦满，口苦咽干，脉弦","消渴，气上撞心，心中疼热，饥不欲食，食则吐蛔","心烦不得眠，口燥咽干，舌尖红，脉细数"],"a":3,"e":"厥阴病为寒热错杂、厥热胜复，其提纲即消渴、气上撞心、心中疼热、饥不欲食、食则吐蛔、下之利不止，是厥阴肝木乘脾、寒热夹杂之象。脉微细、但欲寐为少阴病；身热不恶寒反恶热、汗出脉大为阳明病；寒热往来、胸胁苦满、脉弦为少阳病；心烦不得眠、口燥咽干、脉细数为少阴热化证。吐蛔是厥阴病特征"},{"q":"少阴热化证的临床表现是","o":["脉微细，但欲寐","身热，不恶寒反恶热，汗出，脉大","寒热往来，胸胁苦满，口苦咽干，脉弦","消渴，气上撞心，心中疼热，饥不欲食，食则吐蛔","心烦不得眠，口燥咽干，舌尖红，脉细数"],"a":4,"e":"少阴热化证为阴虚阳亢、心火独亢于上、肾水不足于下，故心烦不得眠、口燥咽干、舌尖红、脉细数，即黄连阿胶汤证，多见热化伤阴。脉微细但欲寐为少阴病提纲、偏于寒化；消渴、气上撞心、食则吐蛔为厥阴病；寒热往来、胸胁苦满为少阳病；身热汗出、脉大为阳明病。心烦不眠是少阴热化特征"},{"q":"少阴病证的主要脉症特征是","o":["脉微细，但欲寐","身热，不恶寒反恶热，汗出，脉大","寒热往来，胸胁苦满，口苦咽干，脉弦","消渴，气上撞心，心中疼热，饥不欲食，食则吐蛔","心烦不得眠，口燥咽干，舌尖红，脉细数"],"a":0,"e":"少阴病为心肾阳虚、阴寒内盛，其提纲即脉微细、但欲寐，脉微示阳气衰微、细示阴血不足、但欲寐为神疲欲睡、似睡非睡，是少阴虚寒的全身反映。消渴、气上撞心、食则吐蛔为厥阴病；身热不恶寒反恶热、汗出脉大为阳明病；寒热往来、胸胁苦满、脉弦为少阳病；心烦不得眠、口燥咽干为少阴热化证。但欲寐是少阴病主症"},{"q":"阳明病的主要脉症特征是","o":["脉微细，但欲寐","身热，不恶寒反恶热，汗出，脉大","寒热往来，胸胁苦满，口苦咽干，脉弦","消渴，气上撞心，心中疼热，饥不欲食，食则吐蛔","心烦不得眠，口燥咽干，舌尖红，脉细数"],"a":1,"e":"阳明病为邪入阳明、里热炽盛、津伤化燥，以胃家实为提纲，主身热、不恶寒反恶热、汗出、脉大，是邪热内盛、蒸腾于外之象。脉微细但欲寐为少阴病；寒热往来、胸胁苦满、脉弦为少阳病；消渴、气上撞心、食则吐蛔为厥阴病；心烦不得眠、口燥咽干、脉细数为少阴热化证。不恶寒反恶热是阳明里热特征"},{"q":"壮热，神昏谵语，面赤气粗，便秘尿黄，苔黄腻，脉滑数，宜诊断为","o":["痰蒙心神证","痰火扰神证","胆郁痰扰证","心火亢盛证","肝阳化风证"],"a":1,"e":"痰火扰神证因痰火内盛、上扰心神、神明失守，故壮热、神昏谵语、面赤气粗、便秘尿黄、苔黄腻、脉滑数，发病急、热象著。痰蒙心神见表情淡漠、喃喃独语、苔腻脉滑而无热象；胆郁痰扰见惊悸失眠、口苦呕恶、脉弦滑；心火亢盛见心烦失眠、口舌生疮、脉数但无痰；肝阳化风见眩晕震颤、肢麻。神昏谵语兼痰火是本证特征"},{"q":"表情淡漠，神志痴呆，精神抑郁，喃喃独语，苔腻，脉滑，宜诊断为","o":["痰蒙心神证","痰火扰神证","胆郁痰扰证","心火亢盛证","肝阳化风证"],"a":0,"e":"痰蒙心神证因痰浊内盛、蒙蔽心窍、神明失守，故表情淡漠、神志痴呆、精神抑郁、喃喃独语、苔腻、脉滑，无发热等热象，起病较缓。痰火扰神见壮热、神昏谵语、面赤气粗、脉滑数；胆郁痰扰见惊悸不寐、口苦呕恶、脉弦滑；心火亢盛见心烦、口舌生疮、脉数；肝阳化风见眩晕抽搐。本证以静默呆滞、无热为特点"},{"q":"腰膝酸软，神疲乏力，小便频数而清，尿后余沥不尽，证属","o":["肾精不足证","肾阳虚证","肾虚水泛证","肾气不固证","肾阴虚证"],"a":3,"e":"肾气不固证因肾气亏虚、封藏失职、膀胱失约，故腰膝酸软、神疲乏力、小便频数而清、尿后余沥不尽、舌淡苔白、脉弱。肾阳虚见畏寒肢冷、阳痿、五更泻等寒象；肾精不足见早衰、发脱齿摇、小儿五迟；肾虚水泛见浮肿、咳喘痰鸣；肾阴虚见潮热盗汗、五心烦热、舌红少苔。尿频余沥是肾气不固特征"},{"q":"身体矮小，头颅狭小，头顶尖圆，智力低下，骨骼萎软，证属","o":["肾精不足证","肾阳虚证","肾虚水泛证","肾气不固证","肾阴虚证"],"a":0,"e":"肾精不足证因肾精亏虚、髓海不足、骨骼失养，故身体矮小、头颅狭小、头顶尖圆、智力低下、骨骼萎软，即五迟五软，多自幼发病。肾气不固见尿频余沥、滑胎、带下清稀；肾阳虚见畏寒肢冷、五更泻；肾虚水泛见浮肿、咳喘；肾阴虚见潮热盗汗、舌红少苔。小儿发育迟缓、囟填尖圆是肾精不足之象"},{"q":"疲乏无力，腰膝酸软，月经淋漓不尽，白带量多清稀，证属","o":["肾精不足证","肾阳虚证","肾虚水泛证","肾气不固证","肾阴虚证"],"a":3,"e":"肾气不固证因肾气亏虚、冲任不固、带脉失约，故腰膝酸软、疲乏无力、月经淋漓不尽、白带量多清稀、舌淡、脉弱。肾精不足见发育迟缓、早衰、发脱齿摇；肾阳虚见畏寒肢冷、五更泻；肾虚水泛见浮肿、咳喘痰鸣；肾阴虚见潮热盗汗、舌红少苔。月经淋漓、带下清稀是肾气不固、冲任失约之象"},{"q":"腰酸膝软，耳鸣耳聋，健忘恍惚，两足萎软，齿摇发脱，证属","o":["肾精不足证","肾阳虚证","肾虚水泛证","肾气不固证","肾阴虚证"],"a":0,"e":"肾精不足证因肾精亏虚、髓海空虚、齿发失养、骨骼失充，故腰酸膝软、耳鸣耳聋、健忘恍惚、两足萎软、齿摇发脱，多见早衰。肾气不固见尿频余沥、滑胎、带下清稀；肾阳虚见畏寒肢冷、阳痿、五更泻；肾虚水泛见浮肿咳喘；肾阴虚见潮热盗汗、舌红少苔。耳鸣齿摇发脱是肾精不足、精亏髓空之象"},{"q":"已自然流产五胎，伴腰膝酸软，神疲乏力，面白无华，证属","o":["肾精不足证","肾阳虚证","肾虚水泛证","肾气不固证","肾阴虚证"],"a":3,"e":"肾气不固证因肾气亏虚、冲任不固、胎元失养，故屡屡滑胎、腰膝酸软、神疲乏力、面白无华、舌淡、脉弱。肾精不足见发育迟缓、早衰、发脱齿摇；肾阳虚见畏寒肢冷、五更泻；肾虚水泛见浮肿、咳喘痰鸣；肾阴虚见潮热盗汗、舌红少苔。滑胎、胎元不固是肾气不固的典型表现，与精亏之发育迟缓不同"},{"q":"患者疼痛时，一般肌肤濡软，按之痛减者，为","o":["虚证","实证","表浅","深部","痰饮"],"a":0,"e":"疼痛而肌肤濡软、按之痛减即喜按，为虚证疼痛，因气血不足、脉络失养、不荣则痛，痛势绵绵、喜温喜按。实证疼痛多硬痛拒按、痛势较剧；病位表浅者轻按即痛；深部者重按始痛；痰饮疼痛多伴胸胁脘腹痞满、水声辘辘、泛吐清水。喜按、按之痛减是虚痛辨证要点"},{"q":"患者疼痛时，硬痛拒按者，为","o":["虚证","实证","表浅","深部","痰饮"],"a":1,"e":"疼痛而硬痛拒按，为实证疼痛，因邪气壅滞、气血不通、不通则痛，痛势较剧、按之痛甚、来势急。虚证疼痛喜按、按之痛减、肌肤濡软、绵绵作痛；病位表浅者轻按即痛；深部者重按始痛；痰饮疼痛伴脘腹痞满、振水声。拒按、硬痛是实痛辨证要点，与虚痛喜按相对"},{"q":"轻按即痛者，病在","o":["虚证","实证","表浅","深部","痰饮"],"a":2,"e":"轻按即痛、痛处浅在，提示病位在表浅、在经络肌肤，邪气初犯、部位不深。虚证疼痛喜按、肌肤濡软；实证疼痛硬痛拒按、痛势较剧；痰饮疼痛伴脘腹痞满、水声辘辘；深部疼痛须重按方显、病在脏腑。按诊轻重可测病位深浅，轻按即痛示病在浅表"},{"q":"肢体瘫痪，卧床年余，气短息弱，食少声低，面色淡白，舌淡，脉弱。为","o":["气虚血瘀证","气阴两虚证","气滞血瘀证","血虚夹瘀证","气血两虚证"],"a":4,"e":"气血两虚证因气血俱虚、肢体经络失养，故肢体瘫痪、卧床年余，兼气短息弱、食少声低、面色淡白、舌淡、脉弱，无明显刺痛瘀象。气虚血瘀见乏力兼刺痛固定、舌暗；气阴两虚见潮热盗汗、舌红少苔；气滞血瘀见胀痛、脉弦涩；血虚夹瘀见头晕眼花、出血色暗、脉细涩。瘫软无力而无痛是气血两虚"},{"q":"右胸部撞伤，胸痛胀闷，动则加剧，局部青紫，拒按，脉弦涩。为","o":["气虚血瘀证","气阴两虚证","气滞血瘀证","血虚夹瘀证","气血两虚证"],"a":2,"e":"气滞血瘀证因跌仆损伤、气滞血瘀、经络不通，故胸痛胀闷、动则加剧、局部青紫、拒按、脉弦涩，胀痛示气滞、青紫刺痛示血瘀。气虚血瘀见乏力、气短、刺痛；气血两虚见面白、气短、舌淡、脉弱；血虚夹瘀见头晕、出血色暗；气阴两虚见潮热盗汗、舌红少苔。外伤胀痛青紫、脉弦涩是气滞血瘀"},{"q":"患内痔，经常出血色黯红，头晕眼花，面色萎黄，舌淡，脉细涩。为","o":["气虚血瘀证","气阴两虚证","气滞血瘀证","血虚夹瘀证","气血两虚证"],"a":3,"e":"血虚夹瘀证因内痔长期出血、血虚失养、兼有瘀滞，故头晕眼花、面色萎黄、舌淡、脉细涩，血色黯红为夹瘀之象。气血两虚见面白气短、食少声低、脉弱但血色不暗；气虚血瘀见气短乏力、刺痛固定；气滞血瘀见胀痛、脉弦涩；气阴两虚见潮热盗汗、舌红少苔。出血致血虚而色暗脉涩是血虚夹瘀"},{"q":"胞衣不下，腹痛拒按，恶露夹血块，气短神疲，乏力声低，脉弱。为","o":["气虚血瘀证","气阴两虚证","气滞血瘀证","血虚夹瘀证","气血两虚证"],"a":0,"e":"气虚血瘀证因气虚推动无力、血行瘀滞、冲任失固，故胞衣不下、腹痛拒按、恶露夹血块，兼气短神疲、乏力声低、脉弱。气血两虚见面白、头晕、舌淡、脉弱但无瘀块腹痛；气滞血瘀见胀痛、脉弦涩而无明显气虚；血虚夹瘀见头晕眼花、出血色暗；气阴两虚见潮热盗汗、舌红少苔。气虚兼瘀、腹痛有块是本证特征"},{"q":"“直中”是指","o":["两经或三经证候同时出现","一经证候已罢，继而出现另一经证候","互为表里的阴阳两经证候同时出现","一经证候未罢，又出现另一经证候","外邪入犯阴经而出现三阴经证候"],"a":4,"e":"直中指外邪不经三阳、直接侵入三阴经而出现三阴经证候，多因正气亏虚、邪气直入，见无热恶寒、脉微细、但欲寐等。两经三经证候同时出现为合病；一经已罢、继见他经为传经；互为表里的阴阳两经同时出现为表里传；一经未罢、又见他经为并病。直中强调不经过三阳而直犯三阴"},{"q":"“合病”是指","o":["两经或三经证候同时出现","一经证候已罢，继而出现另一经证候","互为表里的阴阳两经证候同时出现","一经证候未罢，又出现另一经证候","外邪入犯阴经而出现三阴经证候"],"a":0,"e":"合病指伤寒两经或三经证候同时出现、同时发病，如太阳阳明合病。一经证候已罢、继而出现另一经证候为传经；一经未罢又见另一经证候为并病；互为表里的阴阳两经相传为表里传；外邪直犯三阴为直中。合病强调两经三经证候同时并见"},{"q":"“并病”是指","o":["两经或三经证候同时出现","一经证候已罢，继而出现另一经证候","互为表里的阴阳两经证候同时出现","一经证候未罢，又出现另一经证候","外邪入犯阴经而出现三阴经证候"],"a":3,"e":"并病指一经证候未罢、又出现另一经证候，两经证候重叠并见，如太阳病未解又见阳明病。两经或三经证候同时出现为合病；一经已罢继见他经为传经；互为表里阴阳两经相传为表里传；外邪直犯三阴为直中。并病强调前经未罢、后经又起，与合病之同时发病不同"},{"q":"细脉主要是","o":["脉位的变化","脉宽的变化","脉力的变化","紧张度的变化","节律的变化"],"a":1,"e":"细脉脉细如线、应指明显但脉道狭窄，指脉体宽度的改变，主气血两虚、湿证，因血少不能充盈脉道或湿邪阻压脉管。脉位变化如浮沉；脉力变化如虚实；紧张度变化如弦紧；节律变化如结代促。细脉以脉道狭窄、细直如线为特征，属脉宽改变，与洪脉之脉体宽大相反"},{"q":"弦脉主要是","o":["脉位的变化","脉宽的变化","脉力的变化","紧张度的变化","节律的变化"],"a":3,"e":"弦脉端直以长、如按琴弦、挺然指下，指脉管紧张度增高的改变，主肝胆病、疼痛、痰饮、疟疾、气滞。脉位变化如浮沉；脉宽变化如细洪；脉力变化如虚实；节律变化如结代。弦脉以紧张度高、如按琴弦为特征，与紧脉之紧束有力相类，但弦主肝胆气滞、紧主寒邪"},{"q":"实脉主要是","o":["脉位的变化","脉宽的变化","脉力的变化","紧张度的变化","节律的变化"],"a":2,"e":"实脉三部皆有力、举按充实、应指有力，指脉搏力量的改变，主实证、热结、食积，因邪气盛实、正气不虚、邪正相争有力。脉位变化如浮沉；脉宽变化如细洪；紧张度变化如弦紧；节律变化如结代促。实脉以应指有力、举按皆实为特征，与虚脉之举按无力、脉体空豁相对"},{"q":"痰饮病多见","o":["弦滑脉","浮滑脉","洪数脉","沉涩脉","沉迟脉"],"a":1,"e":"官方答案为【浮滑脉】，但依据教材，正确答案为【弦滑脉】。弦脉主痰饮、滑脉主痰湿，弦滑并见是痰饮病的典型脉象，因痰饮为阴邪内停、气机阻滞、脉气不充而弦滑。浮滑脉浮而主表、滑而主痰，为外感表证夹痰或风痰之脉，病位在表，非痰饮内停之常脉。原答案把表证夹痰之脉误作痰饮病脉，故站不住"},{"q":"胸胁胀痛，胁下痞块刺痛多见于","o":["气血两虚证","气滞血瘀证","气虚血瘀证","气随血脱证","气不摄血证"],"a":1,"e":"气滞血瘀证因气机郁滞、血行瘀阻、经络不通，故胸胁胀痛、胁下痞块刺痛、痛处固定、舌暗、脉弦涩，胀痛与刺痛并见。气血两虚见面白气短、舌淡脉弱；气虚血瘀见少气懒言、刺痛、脉弱；气随血脱见大失血后神昏、呼吸微弱、脉微；气不摄血见出血色淡、气短、脉弱。胀痛刺痛并见、脉弦涩是气滞血瘀"},{"q":"大失血，突然唇淡白，神志不清、呼吸微弱多见于","o":["气血两虚证","气滞血瘀证","气虚血瘀证","气随血脱证","气不摄血证"],"a":3,"e":"气随血脱证因大失血之际、气随血亡、阳气暴脱、血脉空虚，故突然唇淡白、神志不清、呼吸微弱、四肢厥冷、脉微欲绝，病情危笃。气血两虚见面白气短、缓慢起病、脉弱；气滞血瘀见胀痛刺痛、脉弦涩；气虚血瘀见乏力、刺痛、脉弱；气不摄血见慢性出血色淡、气短。暴崩失血后神昏脉微是气随血脱"},{"q":"少气懒言，胸胁或其他部位疼痛如刺，痛处固定多见于","o":["气血两虚证","气滞血瘀证","气虚血瘀证","气随血脱证","气不摄血证"],"a":2,"e":"气虚血瘀证因气虚推动无力、血行滞涩、脉络不通，故少气懒言、胸胁或其他部位疼痛如刺、痛处固定、舌暗、脉弱或涩，气虚与血瘀并见。气血两虚见面白、头晕、舌淡、脉弱但无刺痛；气滞血瘀见胀痛、脉弦涩而无明显气虚；气随血脱见大失血后神昏脉微；气不摄血见出血色淡、气短。少气懒言兼刺痛固定是气虚血瘀"},{"q":"脉“有胃”主要指","o":["从容和缓流利","柔和有力，节律一致","脉率不快，强弱适中","尺脉有力，沉取不绝","不浮不沉，不大不小"],"a":0,"e":"脉有胃气指脉象从容和缓、流利均匀、节律一致、应指柔和，反映脾胃功能正常、气血生化有源，是平脉的首要条件。柔和有力、节律一致为有神；尺脉有力、沉取不绝为有根；脉率不快、强弱适中非胃气之专指；不浮不沉、不大不小描述脉位脉形。有胃重在和缓流利，与有神、有根各有侧重"},{"q":"脉“有神”主要指","o":["从容和缓流利","柔和有力，节律一致","脉率不快，强弱适中","尺脉有力，沉取不绝","不浮不沉，不大不小"],"a":1,"e":"脉有神指脉象柔和有力、节律整齐一致、应指灵动不滞，反映心气充足、气血调和、神气旺盛，虽病而神气未衰则预后较好。从容和缓流利为有胃；尺脉有力、沉取不绝为有根；脉率不快、强弱适中非有神之专指；不浮不沉、不大不小述脉位脉形。有神重在柔和有力、节律一致，与有胃之和缓、有根之尺脉相区别"},{"q":"脉“有根”主要指","o":["从容和缓流利","柔和有力，节律一致","脉率不快，强弱适中","尺脉有力，沉取不绝","不浮不沉，不大不小"],"a":3,"e":"脉有根指尺脉有力、沉取不绝，尺为肾之候、元气之根，反映肾气充足、元气不衰、下焦根基稳固。从容和缓流利为有胃；柔和有力、节律一致为有神；脉率不快、强弱适中非有根之专指；不浮不沉、不大不小述脉位脉形。有根重在尺脉沉取有力，是判断元气盛衰、疾病预后的重要依据"},{"q":"代脉的特征是","o":["脉来缓慢，时有中止，止无定数","脉来一止，止有定数，良久方还","脉来数而时有一止，止无定数","脉来数而时一止，止有定数","脉来艰涩，三五不调"],"a":1,"e":"代脉脉来缓慢、时有中止、止有定数、间歇时间较长（良久方还），主脏气衰微、疼痛、惊恐、跌仆损伤、妊娠，因脏气亏虚、脉气不能相续。脉来缓慢、时有中止、止无定数为结脉；脉来数而时一止、止无定数为促脉；脉数而时一止、止有定数非代脉；脉来艰涩、三五不调为涩脉。止有定数是代脉特征"},{"q":"结脉的特征是","o":["脉来缓慢，时有中止，止无定数","脉来一止，止有定数，良久方还","脉来数而时有一止，止无定数","脉来数而时一止，止有定数","脉来艰涩，三五不调"],"a":0,"e":"结脉脉来缓慢、时有一止、止无定数、间歇时间不定，主阴盛气结、寒痰瘀血、气血虚衰，因阴寒凝结、气血运行不畅、脉气时阻。脉来一止、止有定数、良久方还为代脉；脉来数而时一止、止无定数为促脉；脉数而时一止、止有定数非结脉；脉来艰涩、三五不调为涩脉。结脉以脉缓、止无定数区别于代脉与促脉"},{"q":"促脉的特征是","o":["脉来缓慢，时有中止，止无定数","脉来一止，止有定数，良久方还","脉来数而时有一止，止无定数","脉来数而时一止，止有定数","脉来艰涩，三五不调"],"a":2,"e":"促脉脉来急促、时有一止、止无定数、间歇时间不一，主阳盛实热、气血痰食停滞、亦主脏气衰败，因阳热亢盛、脉气急促而时有郁阻。脉来缓慢、时有中止、止无定数为结脉；脉来一止、止有定数、良久方还为代脉；脉数而时一止、止有定数非促脉；脉来艰涩、三五不调为涩脉。促脉以脉数、止无定数区别于结脉之脉缓"},{"q":"少阴寒化证的临床表现是","o":["少腹急结，其人如狂，小便自利，大便色黑如漆","脐腹胀满硬痛，潮热，大便秘结不通，神昏谵语","腹满而吐，食欲不振，自利，时腹自痛，口不渴","无热恶寒，脉微细，但欲寐，下利肢冷，呕不能食","发热恶寒，小便不利，少腹满，口渴，水入即吐"],"a":3,"e":"少阴寒化证因心肾阳虚、阴寒内盛、阳气衰微，故无热恶寒、脉微细、但欲寐、下利肢冷、呕不能食、舌淡苔白，即四逆汤证，全身虚寒象显著。少腹急结、其人如狂、小便自利、大便色黑为太阳蓄血；脐腹胀满硬痛、潮热便秘、神昏谵语为阳明腑实；腹满而吐、自利、时腹自痛、口不渴为太阴病；发热恶寒、小便不利、少腹满、水入即吐为太阳蓄水"},{"q":"太阳蓄血证的临床表现是","o":["少腹急结，其人如狂，小便自利，大便色黑如漆","脐腹胀满硬痛，潮热，大便秘结不通，神昏谵语","腹满而吐，食欲不振，自利，时腹自痛，口不渴","无热恶寒，脉微细，但欲寐，下利肢冷，呕不能食","发热恶寒，小便不利，少腹满，口渴，水入即吐"],"a":0,"e":"太阳蓄血证因邪热内传、瘀血内停下焦、血热互结，故少腹急结、其人如狂或发狂、小便自利（病在血分不在气分）、大便色黑如漆、脉沉涩，即桃核承气汤证。脐腹胀满硬痛、潮热便秘、神昏谵语为阳明腑实；腹满而吐、自利、口不渴为太阴病；无热恶寒、脉微细、但欲寐、下利肢冷为少阴寒化；发热恶寒、小便不利、少腹满、水入即吐为太阳蓄水"},{"q":"太阳蓄水证的临床表现是","o":["少腹急结，其人如狂，小便自利，大便色黑如漆","脐腹胀满硬痛，潮热，大便秘结不通，神昏谵语","腹满而吐，食欲不振，自利，时腹自痛，口不渴","无热恶寒，脉微细，但欲寐，下利肢冷，呕不能食","发热恶寒，小便不利，少腹满，口渴，水入即吐"],"a":4,"e":"太阳蓄水证因外邪入里、膀胱气化不利、水液停蓄下焦，故发热恶寒、小便不利、少腹满、口渴、水入即吐、舌苔白滑，即五苓散证，病在气分水道。少腹急结、其人如狂、小便自利、大便色黑为太阳蓄血；脐腹胀满硬痛、潮热便秘为阳明腑实；腹满而吐、自利、口不渴为太阴病；无热恶寒、脉微细、但欲寐为少阴寒化。小便不利、水入即吐是蓄水特征"},{"q":"易损伤心脾的是","o":["劳力过度","劳神过度","房劳过度","过逸少动","饮食太过"],"a":1,"e":"劳神过度、思虑伤脾、耗血伤心，心脾两虚、气血不足，故见心悸、失眠、健忘、纳呆、腹胀、便溏、面色萎黄、脉细弱，易损伤心脾。劳力过度耗气伤形，易损肺脾；房劳过度耗伤肾精，易损肾脏；过逸少动致气血运行不畅、脾胃功能减弱；饮食太过损伤胃肠及脾。思虑劳神伤心脾是劳神过度特点"},{"q":"易损伤肺脾的是","o":["劳力过度","劳神过度","房劳过度","过逸少动","饮食太过"],"a":0,"e":"劳力过度、形体劳倦、耗气伤形，肺主气、脾主肌肉四肢，二者首先受累，故易损伤肺脾，见气短乏力、四肢倦怠、食少、自汗、脉虚。劳神过度思虑伤心脾；房劳过度耗伤肾精；过逸少动致气血不畅、脾胃减弱；饮食太过损伤胃肠及脾。体力过劳耗气、肺脾受累是劳力过度特点，与劳神之伤心脾不同"},{"q":"易损伤肾脏的是","o":["劳力过度","劳神过度","房劳过度","过逸少动","饮食太过"],"a":2,"e":"房劳过度、肆意耗泄、肾精亏损、肾气不固，故易损伤肾脏，见腰膝酸软、头晕耳鸣、阳痿遗精、早衰、发脱齿摇、月经不调。劳神过度损伤心脾；劳力过度损伤肺脾；过逸少动致气血不畅、脾胃减弱；饮食太过损伤胃肠及脾。肾藏精、主生殖，房劳耗精伤肾，与劳力劳神所伤脏腑不同"},{"q":"易损伤胃肠及脾的是","o":["劳力过度","劳神过度","房劳过度","过逸少动","饮食太过"],"a":4,"e":"饮食太过、暴饮暴食、饥饱失常，损伤胃肠及脾、运化失职、宿食内停，故见脘腹胀满、嗳腐吞酸、恶心呕吐、泄泻、纳呆。劳神过度损伤心脾；劳力过度损伤肺脾；房劳过度损伤肾脏；过逸少动致气血不畅、脾胃减弱。饮食不节直伤胃肠脾胃，是饮食太过特点，与劳逸所伤各异"},{"q":"红肿高大，根盘紧束，伴有焮热疼痛者","o":["痈","疽","疔","疖","斑"],"a":0,"e":"痈为阳证疮疡，湿热火毒蕴结、气血壅滞于局部，故红肿高大、根盘紧束、伴有焮热疼痛、灼热、易脓易溃易敛，发病急、范围较大。疽为阴证，漫肿无头、皮色不变、不热少痛；疔形小根深、坚硬如钉、发病急骤、痛剧；疖起于浅表、形小而圆、红肿热痛不甚；斑为皮肤色斑、平而不高起。红肿高大、根盘紧束是痈的特征"},{"q":"起于浅表，形小而圆，红肿热痛不甚者","o":["痈","疽","疔","疖","斑"],"a":3,"e":"疖为浅表小疮疡，湿热毒邪轻浅、壅滞局部，故起于浅表、形小而圆、红肿热痛不甚、易脓易溃易愈、无明显全身症状。痈红肿高大、根盘紧束、焮热疼痛；疽漫肿无头、皮色不变、不热少痛；疔形小根深、坚硬如钉、顶白而痛剧、病情凶险；斑为平坦色斑、不高起。形小而浅表、热痛不甚是疖的特征"},{"q":"漫肿无头，肤色不变，不热少痛者","o":["痈","疽","疔","疖","斑"],"a":1,"e":"疽为阴证疮疡，寒痰凝滞、气血亏虚、毒邪内陷、不能外达，故漫肿无头、肤色不变、不热少痛、难脓难溃难敛、病程迁延，全身虚寒象明显。痈红肿高大、根盘紧束、焮热疼痛；疔形小根深、坚硬如钉；疖起于浅表、形小而圆、红肿热痛较轻；斑为平坦色斑、不高起。漫肿色不变、不热少痛是疽的特征"},{"q":"心悸怔忡，胸闷疼痛，脉象细涩。此属","o":["心肾不交证","心脾两虚证","心肾阳虚证","心脉痹阻证","心肝血虚证"],"a":3,"e":"心脉痹阻因瘀血等实邪阻滞心脉，故心悸怔忡、胸闷心痛、脉细涩，痛如针刺为其典型表现。心肾不交以心烦失眠、腰膝酸软、潮热盗汗为主；心脾两虚见心悸食少便溏；心肾阳虚兼畏寒浮肿；心肝血虚见目涩肢麻，均无胸痛脉涩"},{"q":"惊悸失眠，遗精盗汗，脉象细数。此属","o":["心肾不交证","心脾两虚证","心肾阳虚证","心脉痹阻证","心肝血虚证"],"a":0,"e":"心肾不交因肾阴亏于下、心火亢于上，水火不济，故惊悸失眠、遗精盗汗、脉细数。心脾两虚以心悸食少、便溏、面色萎黄为要；心肾阳虚见畏寒肢冷浮肿；心脉痹阻见胸闷刺痛脉涩；心肝血虚见目涩肢麻，遗精盗汗不显"},{"q":"心悸少寐，食少便溏，脉象细弱。此属","o":["心肾不交证","心脾两虚证","心肾阳虚证","心脉痹阻证","心肝血虚证"],"a":1,"e":"心脾两虚因心血不足、脾气虚弱，心神失养则心悸少寐，脾失健运则食少便溏，气血不足故脉细弱。心肾不交见遗精、五心烦热；心肾阳虚见畏寒浮肿；心脉痹阻见胸闷刺痛；心肝血虚见目涩肢麻，均无食少便溏"},{"q":"心悸怔忡，尿少浮肿，脉沉细微。此属","o":["心肾不交证","心脾两虚证","心肾阳虚证","心脉痹阻证","心肝血虚证"],"a":2,"e":"心肾阳虚因阳虚水泛、血脉瘀滞，故心悸怔忡、尿少浮肿、畏寒、脉沉细微。心肾不交以阴虚火旺、遗精盗汗为主；心脾两虚见食少便溏；心脉痹阻见胸闷刺痛、脉涩；心肝血虚见目涩肢麻，均无水肿尿少"},{"q":"食少腹胀，畏冷肢凉，带下清稀量多，舌淡胖，脉迟无力为","o":["脾阳虚证","脾虚气陷证","胃气虚证","脾气虚证","寒湿困脾证"],"a":0,"e":"脾阳虚因中焦虚寒、运化失职，故食少腹胀、畏冷肢凉、带下清稀量多、舌淡胖、脉迟无力。脾气虚仅有食少乏力而无寒象；寒湿困脾以苔白腻、头身困重为主，无畏冷肢凉；脾虚气陷见下脱；胃气虚以胃脘痞满为主"},{"q":"脘腹胀闷，头身困重，肢体浮肿，小便短少，舌胖，苔白腻，脉濡缓为","o":["脾阳虚证","脾虚气陷证","胃气虚证","脾气虚证","寒湿困脾证"],"a":4,"e":"寒湿困脾因寒湿内侵、困遏脾运，故脘腹胀闷、头身困重、肢体浮肿、小便短少、苔白腻、脉濡缓。脾阳虚以畏寒肢冷、脉迟无力为主且无苔腻；脾气虚见食少乏力；胃气虚以胃脘痞满、嗳气为主；均无头身困重苔腻"},{"q":"肾脏病变多见","o":["胸痛","胁痛","腹痛","腰痛","脘痛"],"a":3,"e":"腰为肾之府，肾主骨生髓，肾脏病变如肾虚、肾结石多见腰痛、腰膝酸软。苔白腻、脉濡缓是寒湿困脾的辨证眼目，可与湿热蕴脾的苔黄腻、脉滑数相对照。胸痛定位心肺；胁痛定位肝胆；腹痛定位脾胃大肠；脘痛定位胃腑，均非肾病常见疼痛部位"},{"q":"心肺病变多见","o":["胸痛","胁痛","腹痛","腰痛","脘痛"],"a":0,"e":"胸为心肺所居，心脉痹阻、肺系病变多见胸痛、胸闷、心悸咳喘。肾主骨生髓、主腰脚，肾虚则腰膝酸软、酸痛，劳累加重，与外感腰痛的突然发作不同。胁痛定位肝胆；腰痛定位肾；腹痛定位脾胃肠；脘痛定位胃腑，均非心肺病变常见疼痛部位"},{"q":"肝脏病变多见","o":["胸痛","胁痛","腹痛","腰痛","脘痛"],"a":1,"e":"肝经循行布于胁肋，肝胆病变如肝郁气滞、肝胆湿热多见胁痛、胁胀。胸痛常伴心悸、咳喘，与胁痛之胀满走窜、脘痛之与进食相关可以区分。胸痛定位心肺；腰痛定位肾；腹痛定位脾胃大肠；脘痛定位胃腑，均非肝胆病变常见疼痛部位"},{"q":"胃腑病变多见","o":["胸痛","胁痛","腹痛","腰痛","脘痛"],"a":4,"e":"胃居中焦，主受纳腐熟，胃腑病变如胃痛、胃热多见脘痛、胃脘痞满。胁痛多走窜胀痛，随情绪波动而增减，与刺痛固定不移、隐痛绵绵不绝者不同。胸痛属心肺；胁痛属肝胆；腰痛属肾；腹痛多指脐腹、归属大肠，均非胃腑常见疼痛部位"},{"q":"心悸怔忡，心胸闷痛，身重困倦，苔白腻，脉沉滑或沉涩，证属","o":["气滞心脉证","寒凝心脉证","心阳暴脱证","瘀阻心脉证","痰阻心脉证"],"a":4,"e":"痰阻心脉因痰浊壅塞心脉、胸阳不振，故心胸闷痛、身重困倦、苔白腻、脉沉滑。脘痛多在剑突下，与进食、冷热相关，可伴嗳气吞酸，与脐腹疼痛部位迥异。瘀阻心脉以刺痛、舌紫暗、脉涩为主；寒凝心脉见剧痛、形寒肢冷、脉沉紧；气滞心脉见胀痛、善太息、脉弦，均无身重苔腻"},{"q":"心悸怔忡，突起心胸剧痛，形寒肢冷，舌淡苔白，脉沉紧，证属","o":["气滞心脉证","寒凝心脉证","心阳暴脱证","瘀阻心脉证","痰阻心脉证"],"a":1,"e":"寒凝心脉因寒邪客心、血脉凝滞，故突起心胸剧痛、形寒肢冷、舌淡苔白、脉沉紧。痰阻心脉见闷痛、身重苔腻、脉滑；瘀阻心脉见刺痛、舌紫暗；气滞心脉见胀痛、脉弦；均无骤痛、形寒与脉紧"},{"q":"心悸怔忡，心胸胀痛，伴胁胀，善太息，舌淡红，脉弦，证属","o":["气滞心脉证","寒凝心脉证","心阳暴脱证","瘀阻心脉证","痰阻心脉证"],"a":0,"e":"气滞心脉因气机郁滞、心脉不畅，故心胸胀痛、胁胀、善太息、脉弦。寒凝心脉多因卒感寒邪或阳虚内寒，舌淡苔白、脉沉紧是辨证关键，与痰阻之苔腻脉滑可以区分。寒凝心脉见剧痛、形寒肢冷、脉沉紧；痰阻心脉见闷痛、身重苔腻；瘀阻心脉见刺痛、舌紫暗、脉涩；均无胀痛与太息"},{"q":"心悸怔忡，心胸刺痛，舌黯或有青紫斑点，脉细涩或结代，证属","o":["气滞心脉证","寒凝心脉证","心阳暴脱证","瘀阻心脉证","痰阻心脉证"],"a":3,"e":"瘀阻心脉因瘀血内停、心脉不畅，故心胸刺痛、舌暗或有青紫斑点、脉细涩或结代。气滞心脉以胀痛、胁胀、善太息、脉弦为特征，情志不舒时加重，与瘀阻之刺痛固定不移不同。气滞心脉见胀痛、脉弦；寒凝心脉见剧痛、脉沉紧；痰阻心脉见闷痛、身重苔腻脉滑；均无刺痛与瘀斑"},{"q":"上述哪项为气虚证的临床表现","o":["面色淡青","面色淡白少华","面色苍白","脘腹坠胀，便溏","余沥不尽"],"a":1,"e":"气虚证因气血生化不足、推动无力，故面色淡白少华、气短乏力、脉虚。舌质紫暗、瘀点瘀斑与脉细涩、结代是瘀血内停的客观依据，可与痰阻之苔腻相对照。脘腹坠胀便溏实为气陷证；余沥不尽属气不固证；面色苍白为气脱证；面色淡青多属气滞血瘀或痛证"},{"q":"上述哪项为气陷证的主要临床表现","o":["面色淡青","面色淡白少华","面色苍白","脘腹坠胀，便溏","余沥不尽"],"a":3,"e":"气陷证因气虚升举无力、清阳下陷，故脘腹坠胀、便溏，甚则脱肛、久泻。气虚则气血生化不足、不能上荣于面，故面色淡白少华，伴气短乏力、少气懒言、脉虚无力。面色淡白少华为气虚证；余沥不尽属气不固证；面色苍白属气脱证；面色淡青多属气滞血瘀，均非气陷表现"},{"q":"上述哪项为气不固证的临床表现","o":["面色淡青","面色淡白少华","面色苍白","脘腹坠胀，便溏","余沥不尽"],"a":4,"e":"气不固证因气虚固摄失职，故小便余沥不尽，兼自汗、滑精、带下清稀。气陷以气虚兼下陷为特征，除坠胀便溏外，常见久泻、脱肛、内脏下垂，与气脱之暴脱亡阳不同。脘腹坠胀便溏属气陷证；面色淡白少华为气虚证；面色苍白属气脱证；面色淡青多属气滞血瘀，均非不固表现"},{"q":"上述哪项为气脱证的临床表现","o":["面色淡青","面色淡白少华","面色苍白","脘腹坠胀，便溏","余沥不尽"],"a":2,"e":"气脱证因阳气暴脱、机能衰竭，故面色苍白、气息微弱、脉微细欲绝。气不固以固摄失职为核心，除余沥不尽外，尚见自汗、滑精、带下清稀，与气陷之下脱下坠有别。面色淡白少华为气虚证；余沥不尽属气不固证；脘腹坠胀便溏属气陷证；面色淡青多属气滞血瘀，均非气脱表现"},{"q":"心脾气血两虚证的临床表现是","o":["心烦少寐，腰膝酸软，五心烦热，头晕耳鸣","心悸怔忡，胸闷气短，咳嗽气短，吐痰清稀","心悸怔忡，形寒肢冷，肢体浮肿，唇甲青紫","心悸怔忡，腹胀便溏，皮下出血，神疲乏力","心悸健忘，失眠，两目干涩，肢体麻木"],"a":3,"e":"心脾气血两虚因心血不足、脾气虚弱，故心悸怔忡、腹胀便溏、神疲乏力，脾不统血则皮下出血。心烦腰酸、五心烦热属心肾不交；胸闷、吐痰清稀属心肺气虚；形寒浮肿属心肾阳虚；目涩肢麻属心肝血虚"},{"q":"心肾阳虚证的临床表现是","o":["心烦少寐，腰膝酸软，五心烦热，头晕耳鸣","心悸怔忡，胸闷气短，咳嗽气短，吐痰清稀","心悸怔忡，形寒肢冷，肢体浮肿，唇甲青紫","心悸怔忡，腹胀便溏，皮下出血，神疲乏力","心悸健忘，失眠，两目干涩，肢体麻木"],"a":2,"e":"心肾阳虚因阳虚水泛、血脉瘀滞，故心悸怔忡、形寒肢冷、肢体浮肿、唇甲青紫。心烦腰酸、五心烦热属心肾不交；胸闷吐痰清稀属心肺气虚；腹胀便溏、皮下出血属心脾气血两虚；目涩肢麻属心肝血虚"},{"q":"心肝血虚证的临床表现是","o":["心烦少寐，腰膝酸软，五心烦热，头晕耳鸣","心悸怔忡，胸闷气短，咳嗽气短，吐痰清稀","心悸怔忡，形寒肢冷，肢体浮肿，唇甲青紫","心悸怔忡，腹胀便溏，皮下出血，神疲乏力","心悸健忘，失眠，两目干涩，肢体麻木"],"a":4,"e":"心肝血虚因血虚心神失养、肝血不足，故心悸健忘失眠、两目干涩、肢体麻木。心烦腰酸、五心烦热属心肾不交；胸闷吐痰清稀属心肺气虚；形寒浮肿、唇甲青紫属心肾阳虚；腹胀便溏、皮下出血属心脾气血两虚"},{"q":"湿证是指","o":["某一脏腑经络的气机阻滞，运行不畅所表现的证候","体内水液运化失常而形成的一种弥漫状态的病理物质导致的证候","辨别病因与病性","判断疾病中有无气血亏损或运行障碍的证候","判断疾病中有无津液亏虚或水液停聚的证候"],"a":1,"e":"湿证指水液运化失常、湿邪内停所致的证候，湿为弥漫状态的病理产物。某一脏腑经络气机阻滞不畅实为气滞证；辨别病因与病性属辨证总纲；判断气血亏损或运行障碍是辨气血证候；判断津液亏虚或水液停聚是辨津液证候"},{"q":"辨气血证候是指","o":["某一脏腑经络的气机阻滞，运行不畅所表现的证候","体内水液运化失常而形成的一种弥漫状态的病理物质导致的证候","辨别病因与病性","判断疾病中有无气血亏损或运行障碍的证候","判断疾病中有无津液亏虚或水液停聚的证候"],"a":3,"e":"辨气血证候即判断疾病中有无气血亏虚及运行障碍，如气虚、血瘀、气滞等。气机阻滞不畅是气滞证的定义；水液运化失常成湿是湿证；辨别病因与病性为辨证总纲；津液亏虚或水液停聚属辨津液证候"},{"q":"辨津液证候是指","o":["某一脏腑经络的气机阻滞，运行不畅所表现的证候","体内水液运化失常而形成的一种弥漫状态的病理物质导致的证候","辨别病因与病性","判断疾病中有无气血亏损或运行障碍的证候","判断疾病中有无津液亏虚或水液停聚的证候"],"a":4,"e":"辨津液证候是判断津液亏虚与水液停聚的证候，如津伤、痰饮、水湿。气机阻滞不畅属气滞证；水液运化失常成湿是湿证的定义；辨别病因与病性为辨证总纲；气血亏损或运行障碍属辨气血证候"},{"q":"均与气血两虚有关的脉象是","o":["细脉，濡脉，缓脉","滑脉，紧脉，促脉","短脉，动脉，结脉","细脉，滑脉，紧脉","紧脉，革脉，芤脉"],"a":0,"e":"气血两虚脉象多细、濡、缓：细主血虚，濡主气血不足，缓主气虚。津液亏虚见口渴、皮肤干燥、大便干结，水液停聚见痰饮、水肿、湿邪，二者是辨津液证候的核心。滑紧促多属痰食、寒邪、阳盛热结；短动脉结多属气郁、痛证、阴盛；紧革芤多属寒邪、亡阳失血，均非气血两虚典型脉"},{"q":"均与湿证有关的脉象是","o":["细脉，濡脉，缓脉","滑脉，紧脉，促脉","短脉，动脉，结脉","细脉，滑脉，紧脉","紧脉，革脉，芤脉"],"a":0,"e":"湿证脉多濡、缓、细：濡主湿邪，缓主湿困，细主湿阻气血。缓脉主气虚，濡脉细软主气血俱不足，三者共同指向气血亏虚、脉道不充。滑紧促多属痰食、寒邪、热结；短动脉结多属气郁、痛证、阴盛；紧革芤多属寒邪、亡阳失血，均非湿证典型脉象"},{"q":"均与饮食积滞有关的脉象是","o":["细脉，濡脉，缓脉","滑脉，紧脉，促脉","短脉，动脉，结脉","细脉，滑脉，紧脉","紧脉，革脉，芤脉"],"a":1,"e":"饮食积滞脉多滑、紧、促：滑主食积，紧主积滞，促主食积化热。濡脉浮细而软、缓脉一息四至而怠缓、细脉脉细如线，皆湿性黏滞阻遏脉道之象。细濡缓多属气血两虚或湿证；短动脉结属气郁、痛证、阴盛；革芤属失血亡阳，均非饮食积滞的典型脉象"},{"q":"白睛色红，可见于","o":["肝经风热","外感风热","心火上炎","脾胃湿热","肾精亏耗"],"a":1,"e":"白睛属肺，外感风热犯肺、肺热上蒸，故白睛色红。滑主食积内停、紧主积滞不化、促主食积化热，三者从不同侧面反映食积胃肠的病理变化。肝经风热多见全目赤痛或目眦红；心火上炎多见目眦赤、舌尖红；脾胃湿热多见目胞黄色；肾精亏耗多见目胞黑、目昏干涩，均非白睛红"},{"q":"全目赤痛，可见于","o":["肝经风热","外感风热","心火上炎","脾胃湿热","肾精亏耗"],"a":0,"e":"肝开窍于目，肝经风热上攻于目，故全目赤痛、羞明流泪。白睛属肺称气轮，肺热上蒸则赤，与目眦属心、目胞属脾的部位划分是鉴别要点。外感风热多见白睛红；心火上炎多见目眦赤；脾胃湿热多见目胞黄肿；肾精亏耗多见目昏干涩，均非全目赤痛"},{"q":"目胞色黑，可见于","o":["肝经风热","外感风热","心火上炎","脾胃湿热","肾精亏耗"],"a":4,"e":"肾精亏虚，精气不能上荣于目，故目胞色黑、目昏无光。肝开窍于目，肝火上炎则目赤肿痛、羞明流泪，可伴口苦、脉弦数等肝经实火之象。肝经风热见全目赤痛；外感风热见白睛红；心火上炎见目眦赤；脾胃湿热见目胞黄肿，均非目胞色黑"},{"q":"风寒犯肺证咳痰的特点是","o":["咳脓血痰","干咳痰少","咳痰稀白","咳喘痰鸣","咳痰黄稠"],"a":2,"e":"风寒犯肺因寒邪束表、肺气失宣，津液不化，故咳嗽、痰液稀白。目胞属脾称肉轮，肾精亏虚则目胞晦黑、目昏，与脾虚之目胞浮肿、色淡可以区分。咳痰黄稠属风热犯肺；干咳痰少属燥邪犯肺；咳吐脓血痰属肺痈；咳喘痰鸣属痰饮壅肺，均非风寒犯肺"},{"q":"风热犯肺证咳痰的特点是","o":["咳脓血痰","干咳痰少","咳痰稀白","咳喘痰鸣","咳痰黄稠"],"a":4,"e":"风热犯肺因热邪灼津、肺气上逆，故咳嗽、痰黄稠，兼咽痛口渴。寒邪束肺、津液不化，故痰白清稀量多，多伴鼻塞流清涕、恶寒无汗、脉浮紧。咳痰稀白属风寒犯肺；干咳痰少属燥邪犯肺；咳吐脓血痰属肺痈；咳喘痰鸣属痰饮壅肺，均非风热犯肺"},{"q":"燥邪犯肺证咳痰的特点是","o":["咳脓血痰","干咳痰少","咳痰稀白","咳喘痰鸣","咳痰黄稠"],"a":1,"e":"燥邪犯肺因燥性干涩、损伤肺津，肺气上逆，故干咳无痰或痰少而黏。风热灼津则痰黄黏稠，常伴咽痛、流黄涕、舌尖红、脉浮数，与风寒稀白痰形成对照。咳痰稀白属风寒；咳痰黄稠属风热；咳吐脓血痰属肺痈；咳喘痰鸣属痰饮壅肺，均非燥邪犯肺"},{"q":"濡脉的脉象特征是","o":["沉而细软","浮大中空，如按葱管","浮而细软","浮散无根","浮而搏指，如按鼓皮"],"a":2,"e":"濡脉特征为浮而细软、轻取即得、重按稍减，主虚证与湿证。燥胜则干，肺津受损故干咳无痰或痰少难咯、口鼻干燥，多发于秋季，与风寒、风热有别。沉而细软实为弱脉；浮大中空如按葱管是芤脉；浮散无根是散脉；浮而搏指如按鼓皮是革脉，均非濡脉"},{"q":"芤脉的脉象特征是","o":["沉而细软","浮大中空，如按葱管","浮而细软","浮散无根","浮而搏指，如按鼓皮"],"a":1,"e":"芤脉特征为浮大中空、如按葱管，主突然失血、津液大伤。濡脉主虚证与湿证，浮取细软、沉取更弱，与弱脉沉而细软、浮取不应形成部位差异。沉而细软是弱脉；浮而细软是濡脉；浮散无根是散脉；浮而搏指如按鼓皮是革脉，均非芤脉"},{"q":"革脉的脉象特征是","o":["沉而细软","浮大中空，如按葱管","浮而细软","浮散无根","浮而搏指，如按鼓皮"],"a":4,"e":"革脉浮而搏指、中空外坚、如按鼓皮，主亡血、失精、半产、漏下，精血内虚而阳气外越。芤脉浮大中空如按葱管，边实中虚但不如革脉绷急；洪脉浮大有力、来盛去衰；濡脉浮而细软；散脉浮散无根、至数不齐"},{"q":"虚里按之搏动迟弱，为","o":["宗气内虚","宗气外泄","心气已绝","中气不守","心阳不足"],"a":0,"e":"虚里为心尖搏动之处，按之搏动迟弱无力，提示宗气内虚、心气不足。芤脉主失血伤阴，暴崩、吐血、大下之后多见，脉浮大中空而重按无力，是阴血骤亡的脉象依据。宗气外泄见动而应衣；心气已绝见绝而不应；中气不守多伴中气下陷症状；心阳不足以畏寒胸闷为主，均非搏动迟弱"},{"q":"虚里动而应衣为","o":["宗气内虚","宗气外泄","心气已绝","中气不守","心阳不足"],"a":1,"e":"虚里搏动躁疾、动而应衣，为宗气外泄、宗气不固之象。虚里为胃之大络、宗气汇聚之处，搏动迟弱提示宗气不足、推动无力，多伴气短乏力。宗气内虚见搏动迟弱；心气已绝见绝而不应；中气不守多伴下陷症状；心阳不足见畏寒肢冷胸闷，均非动而应衣"},{"q":"虚里按之绝而不应为","o":["宗气内虚","宗气外泄","心气已绝","中气不守","心阳不足"],"a":2,"e":"虚里按之绝而不应，提示心气已绝、宗气断绝，为病情危重之象。虚里搏动幅度大、动而应衣，为宗气外泄不固，常伴心悸、气短、自汗等虚弱表现。宗气内虚见搏动迟弱；宗气外泄见动而应衣；中气不守见搏动异常伴下陷；心阳不足见畏寒胸闷，均非绝而不应"},{"q":"舌质淡胖而嫩，苔白而润，见于","o":["气虚","血虚","气血两虚","阳虚","气阴两虚"],"a":3,"e":"舌质淡胖而嫩、苔白而润，为阳虚内寒、水湿不化之象。虚里按之全无搏动，是心气衰败、宗气断绝的危候，多见于真心痛、心阳暴脱之末。气虚多舌淡苔薄白；血虚多舌淡白而瘦薄；气血两虚舌淡白瘦薄；气阴两虚舌红少苔，均非淡胖白润"},{"q":"舌痿软而淡白无华者，见于","o":["气虚","血虚","气血两虚","阳虚","气阴两虚"],"a":2,"e":"舌体痿软、淡白无华，因气血亏虚、舌体失养、筋脉无力。阳虚生内寒、水湿不化，故舌体胖嫩有齿痕、苔白润，可伴畏寒肢冷、便溏等虚寒之象。气虚多舌淡苔白；血虚多舌淡白瘦薄；阳虚舌淡胖嫩、苔白润；气阴两虚舌红少苔，均非痿软淡白无华"},{"q":"舌苔少而质淡嫩瘦薄者，见于","o":["气虚","血虚","气血两虚","阳虚","气阴两虚"],"a":4,"e":"舌苔少而质淡嫩瘦薄，为气阴两虚之象：气虚无以充养则淡嫩，阴虚无以濡润则瘦薄苔少。舌痿软而淡白无华，因气血亏虚、舌体筋脉失养，多伴心悸眩晕乏力，与阴虚之舌红绛痿软有别。气虚多舌淡苔薄；血虚舌淡白瘦薄；气血两虚舌痿软淡白；阳虚舌淡胖嫩苔白润，均非此"},{"q":"脉象浮而无根，至数不齐，按之则无者，称为","o":["浮脉","洪脉","芤脉","革脉","散脉"],"a":4,"e":"散脉特征为浮散无根、至数不齐、按之则无，主元气离散。淡嫩为气虚、瘦薄苔少为阴亏，两者并见说明气阴俱损，与单纯阳虚之胖嫩苔润不同。浮脉轻取即得、重按稍减而不空；洪脉浮大有力、来盛去衰；芤脉浮大中空如葱管；革脉浮而搏指如鼓皮，均非散脉"},{"q":"脉象浮大中空，如按葱管，称为","o":["浮脉","洪脉","芤脉","革脉","散脉"],"a":2,"e":"芤脉特征为浮大中空、如按葱管，主失血伤阴。散脉主元气离散、脏腑气血将绝，为危重脉象，与浮脉重按有力、芤脉浮大中空判然有别。浮脉轻取即得；洪脉浮大有力、来盛去衰；革脉浮而搏指如按鼓皮；散脉浮散无根、至数不齐，均非芤脉"},{"q":"脉体宽大而浮，充实有力，来盛去衰者，称为","o":["浮脉","洪脉","芤脉","革脉","散脉"],"a":1,"e":"洪脉特征为脉体宽大、浮大有力、来盛去衰，如波涛汹涌，主气分热盛。芤脉浮大中空而按之无力，主失血伤阴，与吐下、大出血之后相应，与革脉之弦硬外急不同。浮脉轻取即得；芤脉浮大中空；革脉浮而搏指如按鼓皮；散脉浮散无根、至数不齐，均非洪脉"},{"q":"一般情况包括","o":["患者就诊时的时间、姓名、性别、年龄、婚姻状况、职业、居处环境等","患者就诊时的主要症状、体征及持续时间","患者当前所患病证的情况","患者服药时的注意事项、饮食宜忌、起居调摄及其他有针对性的医嘱","患者此次就诊时的症状和体征"],"a":0,"e":"一般情况包括就诊时间、姓名、性别、年龄、婚姻状况、职业、居处环境等基本信息。主要症状、体征及持续时间是主诉；当前所患病证情况是现病史；服药宜忌与起居调摄属医嘱；此次症状和体征属现在症状"},{"q":"医嘱的内容包括","o":["患者就诊时的时间、姓名、性别、年龄、婚姻状况、职业、居处环境等","患者就诊时的主要症状、体征及持续时间","患者当前所患病证的情况","患者服药时的注意事项、饮食宜忌、起居调摄及其他有针对性的医嘱","患者此次就诊时的症状和体征"],"a":3,"e":"医嘱内容包括服药注意事项、饮食宜忌、起居调摄及其他针对性嘱咐。时间姓名性别年龄等属一般情况；主要症状体征及持续时间是主诉；当前病证情况属现病史；此次症状和体征属现在症状"},{"q":"现在症状是指","o":["患者就诊时的时间、姓名、性别、年龄、婚姻状况、职业、居处环境等","患者就诊时的主要症状、体征及持续时间","患者当前所患病证的情况","患者服药时的注意事项、饮食宜忌、起居调摄及其他有针对性的医嘱","患者此次就诊时的症状和体征"],"a":4,"e":"现在症状指患者本次就诊时的症状和体征，是辨证的主要依据。医嘱体现因证施护，服药方法、饮食禁忌、起居调摄均有针对性，是辨证论治的延伸与落实。时间姓名性别等属一般情况；主要症状体征及持续时间是主诉；当前病证情况属现病史；服药宜忌与起居调摄属医嘱"},{"q":"患者长期以渔业为生，近日淋雨后出现脘腹胀闷，口腻纳呆，腹痛便溏，全身困重不适，双下肢轻度浮肿，舌淡胖边有齿痕，苔白腻，脉濡。诊为","o":["湿热蕴脾证","脾虚气陷证","脾阳虚证","脾不统血证","寒湿困脾证"],"a":4,"e":"患者久居潮湿、淋雨受寒，寒湿困脾、运化失司，故脘腹胀闷、口腻纳呆、身重、苔白腻、脉濡。湿热蕴脾以苔黄腻、口苦口臭为主；脾阳虚见畏寒肢冷、脉迟；脾虚气陷见下脱；脾不统血见出血，均非"},{"q":"患者近日饮食辛辣厚味，昨日起出现腹胀，纳呆，身重，晨起时觉恶心，口中黏腻且有臭味，排便不爽，便溏质黏，舌红，苔黄腻，脉滑数，诊为","o":["湿热蕴脾证","脾虚气陷证","脾阳虚证","脾不统血证","寒湿困脾证"],"a":0,"e":"患者嗜食辛辣厚味，湿热内生、困阻脾胃，故腹胀纳呆、口黏口臭、便溏不爽、舌红苔黄腻、脉滑数。寒湿困脾以苔白腻、畏寒为主；脾阳虚见畏寒肢冷脉迟；脾虚气陷见下脱；脾不统血见出血，均非"},{"q":"以手足时时掣动，动作迟缓无力为表现的姿态是","o":["手足拘急","手足蠕动","角弓反张","四肢抽搐","舞蹈病状"],"a":1,"e":"手足蠕动指手足时时掣动、动作迟缓无力，多属阴虚动风。手足拘急为筋脉拘挛不伸；角弓反张为项背强直、身体后仰；四肢抽搐为筋脉挛急弛张交替、动作有力；舞蹈病状为手足不规则舞动，均非"},{"q":"以四肢筋脉挛急与弛张间作，舒缩交替，动作有力为表现的姿态是","o":["手足拘急","手足蠕动","角弓反张","四肢抽搐","舞蹈病状"],"a":3,"e":"四肢抽搐指筋脉挛急与弛张交替、舒缩交替、动作有力，多属肝风内动、热极生风。手足拘急为持续拘挛不伸；手足蠕动动作迟缓无力；角弓反张为项背强直后仰；舞蹈病状为不自主舞动，均非"},{"q":"实热证则","o":["呕吐清水痰涎","呕吐黏痰黄水","呕吐酸臭","呕吐脓汁","呕吐血液"],"a":1,"e":"实热证因热邪犯胃、胃气上逆，故呕吐黏痰黄水，兼口渴、舌红苔黄。抽搐多由热极生风或肝风内动，筋脉拘急与弛张交替、动作有力，与蠕动的迟缓无力形成对照。呕吐清水痰涎属虚寒证；呕吐酸臭多属食积；呕吐脓汁多为胃痈；呕吐血液多为热伤血络或瘀血阻络，均非实热"},{"q":"虚寒证则","o":["呕吐清水痰涎","呕吐黏痰黄水","呕吐酸臭","呕吐脓汁","呕吐血液"],"a":0,"e":"虚寒证因中焦虚寒、胃失温降，故呕吐清水痰涎、无臭味，兼腹痛喜温。热邪犯胃、胃气上逆，故呕吐物黏稠色黄，兼口气臭秽、小便短赤、大便干结。呕吐黏痰黄水属实热证；呕吐酸臭多属食积；呕吐脓汁属胃痈；呕吐血液属热伤络或瘀血，均非虚寒"},{"q":"食少脘痞，食后胀甚，气短神疲，面色萎黄，舌淡，脉弱为","o":["脾阳虚证","脾虚气陷证","胃气虚证","脾气虚证","寒湿困脾证"],"a":2,"e":"胃气虚因胃气不足、受纳失常，故食少脘痞、食后胀甚、气短神疲、面色萎黄、脉弱。脾气虚以食少便溏、四肢乏力为主；脾阳虚见畏寒肢冷；脾虚气陷见下脱；寒湿困脾见苔腻身重，均非食后胀甚"},{"q":"突然昏仆，不省人事，口吐涎沫，喉有痰声，手足抽搐，宜诊断为","o":["痰蒙心神证","痰火扰神证","胆郁痰扰证","心火亢盛证","肝阳化风证"],"a":0,"e":"痰蒙心神因痰浊蒙蔽心窍，故突然昏仆、不省人事、口吐涎沫、喉有痰声、手足抽搐。痰火扰神见神昏谵语、躁扰、痰黄；胆郁痰扰见惊悸失眠、口苦；心火亢盛见心烦失眠、舌赤；肝阳化风见眩晕、半身不遂、脉弦，均非"},{"q":"情志不遂，性情急躁易怒，胸闷胁胀，月经后期色紫黯，脉弦涩的临床意义是","o":["气不摄血证","气滞血瘀证","气虚血瘀证","气血两虚证","气随血脱证"],"a":1,"e":"情志不遂致气机郁滞，故胸闷胁胀、脉弦；气滞则血行瘀阻，故月经后期色紫黯、脉涩，属气滞血瘀。气不摄血见出血、气短乏力；气虚血瘀见乏力、刺痛；气血两虚见面色淡白、眩晕；气随血脱见大出血厥脱，均非"},{"q":"消瘦乏力，纳少，面色萎黄，眩晕心悸，舌淡，脉弱的临床意义是","o":["气不摄血证","气滞血瘀证","气虚血瘀证","气血两虚证","气随血脱证"],"a":3,"e":"消瘦乏力、纳少、面色萎黄属气虚，眩晕心悸、舌淡脉弱属血虚，气血俱虚故为气血两虚证。气不摄血见出血；气滞血瘀见胀痛、紫暗；气虚血瘀见乏力伴刺痛；气随血脱见大出血、四肢厥冷，均非"},{"q":"舌红苔剥，多为","o":["阴虚","血虚","气血两虚","胃阴枯竭，胃乏生气","营血大虚，阳气虚衰"],"a":0,"e":"舌红苔剥为阴虚内热、胃阴不足之象，阴虚火旺则舌红，胃阴伤则苔剥落。血虚多舌淡白；气血两虚舌淡白瘦薄；胃阴枯竭见舌光如镜、全无苔；营血大虚、阳气虚衰见舌淡白或黯淡，均非舌红苔剥"},{"q":"胸痹心痛患者，脉象多见","o":["滑","促","弦","涩","数"],"a":3,"e":"胸痹心痛因心脉瘀阻、气血不通，故脉象多见涩，涩主血瘀、往来艰涩。苔剥落提示胃阴、肾阴受损，阴虚生内热故舌红，与血虚之舌淡白、阳虚之舌淡胖嫩不同。滑脉主痰食；促脉主阳盛热结或气血痰食停滞；弦脉主肝胆病与痛证；数脉主热证，均非胸痹典型脉"},{"q":"心烦不寐患者，脉象多见","o":["滑","促","弦","涩","数"],"a":4,"e":"心烦不寐多因热扰心神、神不安舍，故脉象多数，数主热证。涩脉往来艰涩、如轻刀刮竹，反映心脉瘀阻、血行不畅，是胸痹心血瘀阻的典型脉象。滑脉主痰食；促脉主热结或停滞；弦脉主肝胆病与痛证；涩脉主血瘀、往来不畅，均非心烦不寐典型脉"},{"q":"我国第一部论述病源与证候诊断的专著是","o":["《脉经》","《伤寒论》","《金镜录》","《黄帝内经》","《诸病源候论》"],"a":4,"e":"《诸病源候论》为隋代巢元方所撰，是我国第一部论述病源与证候诊断的专著。《脉经》为王叔和所撰、首部脉学专著；《伤寒论》为张仲景辨证论治专著；《金镜录》是现存首部舌诊专著；《黄帝内经》为医学理论奠基之作，均非"},{"q":"我国现存第一部舌诊专著是","o":["《脉经》","《伤寒论》","《金镜录》","《黄帝内经》","《诸病源候论》"],"a":2,"e":"《金镜录》为我国现存第一部舌诊专著，专论舌象与伤寒辨证。《脉经》是脉学专著；《伤寒论》为辨证论治专著；《诸病源候论》论述病源证候；《黄帝内经》为医学理论经典，均非舌诊专著"},{"q":"便秘，脘腹痞满疼痛，得矢气则减，脉弦者，宜诊断为","o":["肠燥津亏证","胃阴虚证","大肠实热证","胃肠气滞证","胃热证"],"a":3,"e":"胃肠气滞因气机阻滞、传导失司，故便秘、脘腹痞满疼痛、得矢气则减、脉弦。肠燥津亏见便干、舌红少津；胃阴虚见口干、舌红少苔；大肠实热见腹满硬痛、潮热；胃热见胃脘灼痛、消谷善饥，均非"},{"q":"便秘，胃脘灼痛，渴喜冷饮，舌红苔黄，脉滑数者，宜诊断为","o":["肠燥津亏证","胃阴虚证","大肠实热证","胃肠气滞证","胃热证"],"a":4,"e":"胃热证因胃中实热、津液受伤，故便秘、胃脘灼痛、渴喜冷饮、舌红苔黄、脉滑数。肠燥津亏见舌红少津、无灼痛；胃阴虚见饥不欲食、舌红少苔；大肠实热见腹满硬痛、潮热谵语；胃肠气滞见胀痛、得矢气减，均非"},{"q":"症见手足震颤，眩晕耳鸣，形体消瘦，五心烦热，潮热盗汗，舌红少津，脉弦细数，证属","o":["肝阳化风证","热极生风证","阴虚风动证","血虚生风证","肝火炽盛证"],"a":2,"e":"阴虚风动因阴液亏虚、筋脉失养，故手足震颤、眩晕耳鸣、形体消瘦、五心烦热、潮热盗汗、舌红少津、脉弦细数。肝阳化风见眩晕、半身不遂、脉弦有力；热极生风见高热抽搐；血虚生风见肢体麻木、舌淡；肝火炽盛见目赤便秘，均非"},{"q":"症见突然昏倒，不省人事，舌强不语，喉中痰鸣，口眼歪斜，半身不遂，舌红苔腻，脉弦有力，证属","o":["肝阳化风证","热极生风证","阴虚风动证","血虚生风证","肝火炽盛证"],"a":0,"e":"肝阳化风因肝阳上亢、化风夹痰，故突然昏倒、不省人事、舌强不语、口眼歪斜、半身不遂、喉中痰鸣、脉弦有力。热极生风见高热抽搐；阴虚风动见手足震颤、潮热盗汗；血虚生风见麻木、舌淡；肝火炽盛见目赤便秘、无偏瘫，均非"},{"q":"鼻出浊涕而臭者是","o":["鼻渊","肺痈","溃腐疡疮","消渴","鼻痔"],"a":0,"e":"鼻渊因邪犯鼻窍、浊涕壅滞，故鼻流浊涕而臭，兼鼻塞、头痛。肝阳化风以肝肾阴虚为本、肝阳化风为标，故眩晕、肢麻、震颤与腰膝酸软并见，脉弦有力。肺痈见咳吐脓血腥臭痰；溃腐疡疮为体表疮疡溃烂；消渴见多饮多尿消瘦；鼻痔为鼻内赘生物、鼻塞，均非浊涕而臭"},{"q":"咳吐浊痰脓血腥臭者是","o":["鼻渊","肺痈","溃腐疡疮","消渴","鼻痔"],"a":1,"e":"肺痈因热毒壅肺、肉腐成脓，故咳吐浊痰脓血、腥臭异常。鼻渊以鼻流浊涕量多、腥臭、鼻塞、前额头痛为特征，与鼻衄出血、鼻痔赘生物可以区分。鼻渊见鼻流浊涕而臭；溃腐疡疮为体表疮疡溃烂；消渴见三多一少；鼻痔为鼻内赘生物，均非咳吐脓血腥臭痰"},{"q":"代脉的脉象为","o":["脉来时一止，止有定数","脉来坚涩，如轻刀刮竹","脉来一息不足四至","一息4至，脉来怠缓","脉来缓慢，时见一止，止无定数"],"a":0,"e":"代脉特征为脉来时一止、止有定数、良久方还，主脏气衰微或疼痛惊恐。脉来坚涩如轻刀刮竹是涩脉；一息不足四至是迟脉；一息四至、脉来怠缓是缓脉；脉来缓慢、时见一止、止无定数是结脉，均非代脉"},{"q":"结脉的脉象为","o":["脉来时一止，止有定数","脉来坚涩，如轻刀刮竹","脉来一息不足四至","一息4至，脉来怠缓","脉来缓慢，时见一止，止无定数"],"a":4,"e":"结脉特征为脉来缓慢、时见一止、止无定数，主阴盛气结、寒痰瘀血。脉来时一止、止有定数是代脉；脉来坚涩如轻刀刮竹是涩脉；一息不足四至是迟脉；一息四至、脉来怠缓是缓脉，均非结脉"},{"q":"症见发热恶寒，头痛无汗或少汗咳嗽，口渴，舌尖边红，脉浮数，其辨证为","o":["卫分证","气分证","营分证","血分证","气血两燔证"],"a":0,"e":"卫分证为温病初起，邪郁卫表、肺气失宣，故发热恶寒、头痛无汗、咳嗽、舌尖边红、脉浮数。气分证见壮热不恶寒、口渴苔黄；营分证见身热夜甚、舌绛；血分证见斑疹出血；气血两燔见气分血分证并见，均非"},{"q":"症见身热夜甚，口干不欲饮，或斑疹隐隐，心烦，或时有谵语，舌绛，脉细数，其辨证为","o":["卫分证","气分证","营分证","血分证","气血两燔证"],"a":2,"e":"营分证因热入营阴、耗伤营血、扰动心神，故身热夜甚、口干不欲饮、心烦谵语、舌绛、斑疹隐隐、脉细数。卫分证见发热恶寒、脉浮数；气分证见壮热苔黄；血分证见斑疹密布、出血；气血两燔见壮热与出血并见，均非"},{"q":"痰白而清稀，或有灰黑点者","o":["热痰","寒痰","风痰","湿痰","燥痰"],"a":1,"e":"寒痰因寒邪凝滞、津液不化，故痰白而清稀，或夹灰黑点。热入营分、耗伤营阴，故身热夜甚、舌绛少苔，与气分之壮热苔黄、血分之出血斑疹递进有别。热痰见痰黄稠；风痰见痰清稀多泡沫、伴眩晕；湿痰见痰白滑、量多易咯；燥痰见痰少而黏、难于咯出，均非寒痰"},{"q":"痰少而黏，难于咯出者，属","o":["热痰","寒痰","风痰","湿痰","燥痰"],"a":4,"e":"燥痰因燥邪伤津、痰液黏稠，故痰少而黏、难于咯出。寒痰多见于阳虚寒盛之人，痰白清稀量多，常伴畏寒、舌淡苔白，与热痰黄稠、燥痰黏少迥异。热痰见痰黄稠；寒痰见痰白清稀或夹灰黑点；风痰见泡沫痰伴表证；湿痰见痰白量多、易于咯出，均非燥痰"},{"q":"恶寒发热，体温38.7℃，咳嗽气喘，无汗口渴，舌红苔黄，脉数。证属","o":["表寒里热证","表热里寒证","真寒假热证","真热假寒证","上寒下热证"],"a":0,"e":"表寒里热因外感寒邪束表则恶寒发热、无汗、头身痛，里有热邪则口渴、舌红苔黄、脉数、咳喘，故为表寒里热。表热里寒见发热、便溏尿清；真寒假热见面红、下利清谷、脉微；真热假寒见肢冷、胸腹灼热；上寒下热见胃寒、尿黄，均非"},{"q":"胸腹灼热，口渴尿黄，烦躁不宁，四肢不温，脉沉而有力。证属","o":["表寒里热证","表热里寒证","真寒假热证","真热假寒证","上寒下热证"],"a":3,"e":"真热假寒因里热炽盛、阳气郁闭于内，故胸腹灼热、口渴尿黄、烦躁、脉沉有力，外现四肢不温的假寒之象。表寒里热见恶寒无汗、口渴；表热里寒见发热、便溏；真寒假热见面红、下利清谷、脉微；上寒下热见胃寒尿黄，均非"},{"q":"水停证的最主要表现是","o":["身体困重疲乏","水肿小便不利","腹满叩之声浊","舌苔滑脉濡缓","胀甚按之即起"],"a":1,"e":"水停证因水液代谢失常、泛溢肌肤，故以水肿、小便不利为主要表现。肢冷为假寒、胸腹灼热为真热，脉沉而有力是辨别关键，与真寒假热之脉微细欲绝截然相反。身体困重疲乏是湿证表现；腹满叩之声浊是水停腹腔；舌苔滑、脉濡缓是湿象；胀甚按之即起属气肿，均非水停主症"},{"q":"水停腹腔的主要表现是","o":["身体困重疲乏","水肿小便不利","腹满叩之声浊","舌苔滑脉濡缓","胀甚按之即起"],"a":2,"e":"水停腹腔即腹水，因水液停聚腹中，故腹满、叩之声浊。水液泛溢肌肤则水肿，下焦气化不利则小便短少，二者是水停证最基本、最具特征的表现。水肿小便不利是水停肌肤；身体困重疲乏属湿证；舌苔滑、脉濡缓为湿象；胀甚按之即起属气肿，均非水停腹腔表现"},{"q":"气分热盛的脉象可见","o":["洪数脉","弦数脉","浮数脉","滑数脉","细数脉"],"a":0,"e":"气分热盛因里热炽盛、脉道充盈，故脉见洪数，洪主热盛、数主热。腹内停水则腹部胀满，叩诊呈浊音或实音，与气胀之叩之鼓音、胀随矢气减轻可以区分。弦数脉多属肝郁化火；浮数脉多属风热表证；滑数脉多属食积或痰热；细数脉多属阴虚内热，均非气分热盛"},{"q":"食积内热的脉象可见","o":["洪数脉","弦数脉","浮数脉","滑数脉","细数脉"],"a":3,"e":"食积内热因食积化热、气血涌盛，故脉见滑数，滑主食积、数主内热。里热炽盛、气血涌盛于脉，故脉来洪大有力、至数偏快，与阴虚细数、表证浮数在脉力上明显不同。洪数脉属气分热盛；弦数脉属肝郁化火；浮数脉属风热表证；细数脉属阴虚内热，均非食积内热"},{"q":"大便秘结，舌红少苔，脉细数者， 属","o":["热结便秘","寒凝便秘","阴虚便秘","气虚便秘","血虚便秘"],"a":2,"e":"阴虚便秘因阴液亏虚、肠道失润，故大便秘结、舌红少苔、脉细数。热结便秘见苔黄厚燥、脉沉数；寒凝便秘见肢冷、脉沉迟；气虚便秘见气短乏力、排便无力；血虚便秘见面色淡白、脉细，均非"},{"q":"大便秘结，舌苔黄厚而燥，脉沉数者，属","o":["热结便秘","寒凝便秘","阴虚便秘","气虚便秘","血虚便秘"],"a":0,"e":"热结便秘因实热内结、肠道燥化，故大便秘结、舌苔黄厚而燥、脉沉数。阴虚便秘因肠道失润、津亏血少，故大便干结如羊屎，兼口干、舌红少苔，与热结之苔黄燥有别。阴虚便秘见舌红少苔、脉细数；寒凝便秘见肢冷、脉沉迟；气虚便秘见气短乏力；血虚便秘见淡白、脉细，均非"},{"q":"朝食暮吐，暮食朝吐，证属","o":["热扰神明","脾胃虚寒","食滞胃肠","脾胃阳虚","饮留于胃"],"a":3,"e":"脾胃阳虚致胃反，因中焦阳虚、腐熟无权，故朝食暮吐、暮食朝吐、完谷不化。热扰神明见神昏谵语、呕吐；食滞胃肠见呕吐酸腐、嗳气；脾胃虚寒见呕吐清水、腹痛喜温；饮留于胃见口干、饮后则吐，均非"},{"q":"口干欲饮，饮后则吐，证属","o":["热扰神明","脾胃虚寒","食滞胃肠","脾胃阳虚","饮留于胃"],"a":4,"e":"饮留于胃因水饮停胃、胃气上逆，故口干欲饮、饮后则吐，称为水逆。朝食暮吐、暮食朝吐为胃反，因脾胃阳虚、腐熟无权、宿食不化，多伴腹痛喜温、舌淡苔白。热扰神明见神昏谵语；脾胃虚寒见呕吐清水、腹痛喜温；食滞胃肠见呕吐酸腐；脾胃阳虚见朝食暮吐，均非"},{"q":"肌肤按之凹陷，不能即起者，为","o":["水肿","气肿","血肿","痰核","痞满"],"a":0,"e":"水肿因水液泛溢肌肤、潴留组织间隙，故肌肤按之凹陷、不能即起，为凹陷性水肿。气肿按之凹陷、抬手即起；血肿为局部瘀血肿块、色紫暗；痰核为皮下结节、推之可移；痞满为自觉胀满、按之无形，均非"},{"q":"肌肤按之凹陷，抬手即起者，为","o":["水肿","气肿","血肿","痰核","痞满"],"a":1,"e":"气肿因气机郁滞、气体充斥肌肤，故按之凹陷、抬手即起。水肿为水液泛溢肌肤、潴留组织间隙，按之凹陷难起，多伴小便不利、眼睑或下肢浮肿。水肿按之凹陷、不能即起；血肿为瘀血肿块、色紫暗；痰核为皮下结节、推之可移；痞满为自觉胀满、无外形改变，均非"},{"q":"湿热蕴脾可见","o":["尿频尿急，尿道灼痛，尿黄短少","头痛目赤，急躁易怒，胁痛便秘","腹部痞闷，纳呆便溏，面目发黄","腹痛下痢，赤白黏冻，里急后重","阴囊湿疹，瘙痒难忍，小便短赤"],"a":2,"e":"湿热蕴脾因湿热内蕴、脾胃运化失司，故腹部痞闷、纳呆便溏、面目发黄，属阳黄。尿频尿急、尿道灼痛属膀胱湿热；头痛目赤、急躁便秘属肝胆火旺；腹痛下痢、里急后重属大肠湿热；阴囊湿疹瘙痒属肝胆湿热，均非"},{"q":"肝胆湿热可见","o":["尿频尿急，尿道灼痛，尿黄短少","头痛目赤，急躁易怒，胁痛便秘","腹部痞闷，纳呆便溏，面目发黄","腹痛下痢，赤白黏冻，里急后重","阴囊湿疹，瘙痒难忍，小便短赤"],"a":4,"e":"肝胆湿热因湿热循肝经下注，故阴囊湿疹、瘙痒难忍、小便短赤，兼胁痛口苦。尿频尿急灼痛属膀胱湿热；头痛目赤、急躁便秘属肝火炽盛；腹部痞闷、面目发黄属湿热蕴脾；腹痛下痢、里急后重属大肠湿热，均非"},{"q":"望舌辨虚实，主要观察","o":["舌色浅深","舌质老嫩","舌苔厚薄","舌苔润燥","舌体胖瘦"],"a":1,"e":"望舌辨虚实主要观察舌质老嫩：舌质苍老坚敛多属实，胖嫩浮肿多属虚。肝经循行绕阴器，肝胆湿热下注则阴囊湿疹、瘙痒、小便短赤，兼口苦、胁痛、脉弦数。舌色浅深主寒热；舌苔厚薄主邪气深浅；舌苔润燥主津液盈亏；舌体胖瘦虽可候虚实但以老嫩为辨证要点，均非首选"},{"q":"反映体内津液盈亏和输布情况，主要观察","o":["舌色浅深","舌质老嫩","舌苔厚薄","舌苔润燥","舌体胖瘦"],"a":3,"e":"舌苔润燥直接反映体内津液的盈亏与输布：苔润为津液充足、输布正常，苔燥为津伤或输布失常。舌色浅深主寒热；舌质老嫩主虚实；舌苔厚薄主邪气深浅；舌体胖瘦多主水湿或虚实，均非津液盈亏"},{"q":"小儿食指络脉色鲜红主病","o":["外感表证","内热","惊风证","痛证","虚证"],"a":0,"e":"小儿食指络脉色鲜红主外感表证，多属风寒，因邪在表、气血外趋。苔润为津液上承、输布正常，苔燥甚至干裂为津伤或输布失司，可据此判断津液盈亏与气化。络脉紫红主内热；色青紫或紫黑、形态迂曲主惊风；色青紫亦主痛证；色淡白主虚证，均非鲜红所主"},{"q":"小儿食指络脉色淡主病","o":["外感表证","内热","惊风证","痛证","虚证"],"a":4,"e":"小儿食指络脉色淡主虚证，因气血不足、络脉不充。小儿指纹浮露、色鲜红，多属外感风寒初起，邪在表、正气抗邪于外，常伴发热恶寒、无汗。色鲜红主外感表证；色紫红主内热；色青紫迂曲主惊风；色青紫亦主痛证，均非色淡所主"},{"q":"实热壅肺可见","o":["喘","哮","声重","少气","太息"],"a":0,"e":"实热壅肺因邪热壅肺、肺气上逆，故见喘，表现为呼吸急促、气喘抬肩。指纹色淡、推之不显，因气血亏虚、络脉不充，多见于脾胃虚弱、久病体虚的小儿。哮为痰饮宿疾、喉中痰鸣；声重多为外感风寒、鼻塞；少气为气虚；太息为肝郁气滞，均非实热壅肺"},{"q":"痰饮宿疾可见","o":["喘","哮","声重","少气","太息"],"a":1,"e":"哮为痰饮宿疾，因痰饮内伏于肺、遇感引触，故喉中痰鸣、反复发作。邪热壅肺、肺气上逆则喘促气粗，喉间痰鸣不显，与哮证之宿痰内伏、喉中哮鸣反复发作不同。喘多因实热壅肺或肺气上逆；声重多为风寒鼻塞；少气属气虚；太息属肝郁气滞，均非痰饮宿疾"},{"q":"六经辨证体系属于","o":["病证横向传变的定位方法","病证纵向传变的定位方法","辨别病证在不同脏腑的定位方法","辨别病证在气、在血的定位方法","根据经络循行路线定位的方法"],"a":0,"e":"六经辨证以太阳、阳明、少阳、太阴、少阴、厥阴分证，按表里、寒热、虚实依次横向展开并传变，故属病证横向传变的定位方法。辨别病证在不同脏腑是脏腑辨证；辨别在气在血是气血辨证；依经络循行路线定位是经络辨证，均非六经"},{"q":"卫气营血辨证体系属于","o":["病证横向传变的定位方法","病证纵向传变的定位方法","辨别病证在不同脏腑的定位方法","辨别病证在气、在血的定位方法","根据经络循行路线定位的方法"],"a":0,"e":"卫气营血辨证以卫、气、营、血四个层次分证，病位由表入里、横向递变，故属病证横向传变的定位方法。辨别病证在不同脏腑是脏腑辨证；辨别在气在血是气血辨证；依经络循行路线定位是经络辨证，均非卫气营血"},{"q":"食积胃肠多为","o":["口气酸臭","口气腥臭","口气腐臭","口气臭秽","口气臊臭"],"a":0,"e":"食积胃肠因宿食停滞、腐浊上泛，故口气酸臭，兼嗳气酸腐、脘腹胀满。口气腥臭多属肺痈或龈齿化脓；口气腐臭多为内有疮疡溃腐；口气臭秽多属胃热；口气臊臭多属肝经湿热或肾病，均非食积"},{"q":"胃热多为","o":["口气酸臭","口气腥臭","口气腐臭","口气臭秽","口气臊臭"],"a":3,"e":"胃热因胃中实热、浊气上泛，故口气臭秽，兼口渴喜冷、牙龈肿痛。食积胃肠、宿食腐化，故口气酸腐，兼嗳气吞酸、脘腹胀满、大便酸臭，与胃热口臭之臭秽不同。口气酸臭属食积胃肠；口气腥臭多属肺痈；口气腐臭属疮疡溃腐；口气臊臭属肝经湿热，均非胃热"},{"q":"阴虚潮热可见","o":["身热不扬","高热不退","午后低热","日晡潮热","发热重恶寒轻"],"a":2,"e":"阴虚潮热因阴液亏虚、虚火内扰，故午后或入夜低热、五心烦热、盗汗。胃中实热、浊气上泛，故口气臭秽，兼牙龈肿痛、渴喜冷饮、大便干结，与食积酸腐气味有别。身热不扬多属湿温；高热不退多属实热；日晡潮热属阳明腑实；发热重恶寒轻属风热表证，均非阴虚潮热"},{"q":"阳明潮热可见","o":["身热不扬","高热不退","午后低热","日晡潮热","发热重恶寒轻"],"a":3,"e":"阳明潮热因阳明腑实、燥屎内结，故日晡潮热，兼腹满硬痛、便秘。阴虚生内热，午后及入夜阳气入里、虚火内扰，故低热、五心烦热、盗汗、舌红少苔、脉细数。身热不扬多属湿温；高热不退多属实热；午后低热属阴虚潮热；发热重恶寒轻属风热表证，均非阳明潮热"},{"q":"左少腹作痛，按之累累，有硬块者多为","o":["肠痈","痛经","泄泻","虫积","燥屎"],"a":4,"e":"左少腹为乙状结肠所在，按之累累有硬块、作痛，为燥屎内结、肠道传导失司。肠痈痛在右下腹、拒按有包块；痛经痛在小腹、与月经相关；泄泻以大便稀溏为主；虫积多见脐周疼痛，均非左少腹硬块"},{"q":"右下腹作痛而拒按，按之有包块应手者为","o":["肠痈","痛经","泄泻","虫积","燥屎"],"a":0,"e":"肠痈因热毒瘀滞肠腑，故右下腹疼痛拒按、按之有包块应手，相当于阑尾炎。左少腹为乙状结肠部位，燥屎内结、腑气不通则按之累累有硬块、作痛，伴便秘、苔黄燥。燥屎在左少腹、按之累累；痛经在小腹、与经期相关；泄泻以便溏为主；虫积多在脐周，均非右下腹包块"},{"q":"实热证的汗出特点为","o":["醒时汗出，动则加重","睡时汗出，醒则汗止","发热而大汗出","半身汗出","冷汗淋漓"],"a":2,"e":"实热证因里热炽盛、迫津外泄，故发热而大汗出，兼口渴、脉数。醒时汗出、动则加重属气虚自汗；睡时汗出、醒则汗止属阴虚盗汗；半身汗出多属中风偏枯；冷汗淋漓属亡阳，均非实热大汗"},{"q":"亡阳证的汗出特点为","o":["醒时汗出，动则加重","睡时汗出，醒则汗止","发热而大汗出","半身汗出","冷汗淋漓"],"a":4,"e":"亡阳证因阳气暴脱、卫外不固，故冷汗淋漓、四肢厥冷、脉微欲绝。醒时汗出、动则加重属气虚自汗；睡时汗出、醒则汗止属阴虚盗汗；发热大汗属实热；半身汗出属中风偏枯，均非冷汗淋漓"},{"q":"肝火炽盛证属于","o":["实证","虚证","上实下虚证","上虚下实证","寒热错杂证"],"a":0,"e":"肝火炽盛因肝经实火亢盛，纯属实证，故见目赤、急躁易怒、便秘尿黄、脉弦数。亡阳因阳气骤脱、固摄无权，故冷汗淋漓、汗出如珠，兼四肢厥冷、脉微细欲绝，属危候。虚证以正气不足为主；上实下虚如肝阳上亢；上虚下实与本证相反；寒热错杂为寒热并见，均非单纯实证"},{"q":"肝阳上亢证属于","o":["实证","虚证","上实下虚证","上虚下实证","寒热错杂证"],"a":2,"e":"肝阳上亢因肝肾阴虚于下、肝阳上扰于上，故属上实下虚证，见眩晕头胀、腰膝酸软。肝火炽盛为肝经实热，起病急、症状剧，见目赤肿痛、头痛、便秘、脉弦数，与肝阳上亢之上实下虚有别。实证如肝火炽盛纯实；虚证为纯虚；上虚下实与本证相反；寒热错杂为寒热并见，均非肝阳上亢"},{"q":"月经先期10余天，经色深红，量多质稠，心烦口渴，舌绛，脉滑数，证属","o":["血寒证","阳虚证","阴虚证","血热证","亡阳证"],"a":3,"e":"血热证因热迫血行、血海不固，故月经先期、量多、色深红质稠、心烦口渴、舌绛脉数。血寒证见月经后期、色暗、少腹冷痛；阳虚证见畏寒、月经后期；阴虚证见潮热、经色鲜红量少；亡阳证见大汗厥冷，均非"},{"q":"因行经期受寒淋雨，而月经延迟，少腹冷痛，拒按，脉沉弦，为","o":["血寒证","阳虚证","阴虚证","血热证","亡阳证"],"a":0,"e":"血寒证因寒邪客于胞宫、血行凝滞，故月经后期、少腹冷痛拒按、脉沉弦。血热迫血妄行、血海不固，故月经先期量多、色深红质稠，兼心烦口渴、舌绛、脉滑数。阳虚证虽畏寒但多虚寒喜按；阴虚证见潮热盗汗；血热证见月经先期、量多色红；亡阳证见大汗肢冷、脉微，均非"},{"q":"患者舌色青紫而润，主病为","o":["气滞血瘀","气虚血瘀","寒凝血瘀","热灼营阴","血虚夹瘀"],"a":2,"e":"舌色青紫而润为寒凝血瘀之象，寒主收引、血行不畅，故舌紫暗而湿润。血寒因寒凝胞宫、血行不畅，故月经后期、量少色暗、少腹冷痛拒按，得温痛减，脉沉弦。气滞血瘀舌紫暗但多伴胀痛；气虚血瘀舌淡紫、乏力；热灼营阴舌红绛少津；血虚夹瘀舌淡白有瘀点，均非青紫而润"},{"q":"卫分证的主要病理是","o":["邪郁卫表，肺气失宣","里热蒸迫，热炽津伤","营热耗伤，扰神窜络","动血耗血，瘀热内阻","邪热内陷，机窍阻闭"],"a":0,"e":"卫分证为温病初起，邪郁卫表、肺气失宣，故发热恶寒、头痛咳嗽、脉浮数。里热蒸迫、热炽津伤是气分证；营热耗伤、扰神窜络是营分证；动血耗血、瘀热内阻是血分证；邪热内陷、机窍阻闭是热陷心包，均非卫分"},{"q":"气分证的主要病理是","o":["邪郁卫表，肺气失宣","里热蒸迫，热炽津伤","营热耗伤，扰神窜络","动血耗血，瘀热内阻","邪热内陷，机窍阻闭"],"a":1,"e":"气分证因邪入气分、里热蒸迫、热炽津伤，故壮热不恶寒、口渴、苔黄。邪郁卫表、肺气失宣是卫分证；营热耗伤、扰神窜络是营分证；动血耗血、瘀热内阻是血分证；邪热内陷、机窍阻闭是热闭心包，均非气分"},{"q":"胸中烦热，频欲呕吐，腹痛喜暖，大便稀薄者，证属","o":["表热里寒","表寒里热","上热下寒","上寒下热","真寒假热"],"a":2,"e":"上热下寒因上焦有热则胸中烦热、频欲呕吐，下焦有寒则腹痛喜暖、大便稀薄。表热里寒见发热、便溏尿清；表寒里热见恶寒无汗、口渴苔黄；上寒下热与上相反；真寒假热见面红、下利清谷、脉微，均非"},{"q":"恶寒发热，无汗，头身强痛，咳嗽黄痰，烦躁脉数，证属","o":["表热里寒","表寒里热","上热下寒","上寒下热","真寒假热"],"a":1,"e":"表寒里热因外寒束表则恶寒发热、无汗、头身强痛，里热内蕴则咳嗽黄痰、烦躁脉数。表热里寒见发热、便溏尿清；上热下寒见胸中烦热、腹痛喜暖；上寒下热见胃寒、尿黄；真寒假热见面红、下利、脉微，均非"},{"q":"黄色鲜明如橘子色，伴有汗，尿色深黄如黄柏汁，口渴，舌苔黄腻者","o":["阳黄","阴黄","萎黄","苍黄","黄胖"],"a":0,"e":"阳黄因湿热蕴结肝胆、胆汁外溢，故黄色鲜明如橘子色、尿色深黄如黄柏汁、口渴、舌苔黄腻，兼有汗。阴黄见黄色晦暗如烟熏、畏寒、苔白腻；萎黄面黄无光泽、无黄染；苍黄为黄而晦暗；黄胖为黄而虚浮，均非阳黄"},{"q":"黄色晦暗如烟熏，伴有畏寒，口淡，舌苔白腻者","o":["阳黄","阴黄","萎黄","苍黄","黄胖"],"a":1,"e":"阴黄因寒湿困阻肝胆、胆汁外溢，故黄色晦暗如烟熏、畏寒口淡、舌苔白腻。阳黄见黄色鲜明、口渴、苔黄腻、尿黄如柏汁；萎黄面黄无光、无黄染；苍黄为黄而暗滞；黄胖为黄而浮肿，均非阴黄"},{"q":"嗜食异物可见于","o":["大肠湿热证","肠虚滑泻证","肠燥津亏证","虫积肠道证","肠热腑实证"],"a":3,"e":"虫积肠道因寄生虫内扰、脾胃受损，故嗜食异物如泥土、生米，兼面黄肌瘦、腹痛。大肠湿热见腹痛下痢、里急后重；肠虚滑泻见久泻滑脱；肠燥津亏见便秘；肠热腑实见腹满硬痛、潮热，均非"},{"q":"里急后重可见于","o":["大肠湿热证","肠虚滑泻证","肠燥津亏证","虫积肠道证","肠热腑实证"],"a":0,"e":"大肠湿热因湿热蕴结大肠、气机阻滞，故腹痛下痢、赤白黏冻、里急后重。肠虚滑泻见久泻滑脱、无里急后重；肠燥津亏见便秘；虫积肠道见嗜食异物；肠热腑实见腹满硬痛、潮热谵语，均非"},{"q":"营分证的辨证要点是","o":["发热恶风寒，口渴","壮热不恶寒，口渴，苔黄","身热夜甚，心烦谵语，舌红绛","斑疹，出血，舌质深绛","身热，脘痞，呕恶苔腻"],"a":2,"e":"营分证因热入营阴、扰神伤络，辨证要点为身热夜甚、心烦谵语、舌红绛，兼斑疹隐隐。发热恶寒、口渴是卫分；壮热不恶寒、苔黄是气分；斑疹出血、舌深绛是血分；身热脘痞、呕恶苔腻是湿热，均非营分"},{"q":"血分证的辨证要点是","o":["发热恶风寒，口渴","壮热不恶寒，口渴，苔黄","身热夜甚，心烦谵语，舌红绛","斑疹，出血，舌质深绛","身热，脘痞，呕恶苔腻"],"a":3,"e":"血分证因热入血分、动血耗血，辨证要点为斑疹密布、出血、舌质深绛、神昏。发热恶寒、口渴属卫分；壮热、苔黄属气分；身热夜甚、舌红绛属营分；身热脘痞、呕恶苔腻属湿热，均非血分"},{"q":"望小儿食指指纹，指纹淡滞的意义是","o":["分表里","定虚实","辨寒热","测轻重","估预后"],"a":1,"e":"望小儿食指指纹以淡滞定虚实：纹淡色浅多属虚，纹滞色深多属实。血分证为温病最深阶段，热盛动血则斑疹密布、出血，舌深绛少苔，与营分之舌红绛、斑疹隐隐在程度上递进。浮沉分表里；红紫辨寒热；三关测轻重；估预后需综合判断，均非淡滞所主"},{"q":"望小儿食指指纹，指纹红紫的意义是","o":["分表里","定虚实","辨寒热","测轻重","估预后"],"a":2,"e":"指纹红紫辨寒热：色鲜红多属风寒表证，紫红多属热，青紫多属惊风或痛证。指纹淡而细多虚、滞而粗多实，是判断小儿正气盛衰与邪气虚实的重要依据，需结合形态色泽综合判断。浮沉分表里；淡滞定虚实；三关测轻重；估预后需综合判断，均非红紫所主"},{"q":"症见渴喜热饮，饮量不多者，其病机是","o":["寒湿内盛","湿热内蕴","痰饮内停","瘀血阻滞","胃阴不足"],"a":2,"e":"渴喜热饮而饮量不多，因痰饮内停、津液不能上承，故虽渴而不欲多饮。寒湿内盛见口淡不渴；湿热内蕴见口渴喜冷；瘀血阻滞见口燥但欲漱水不欲咽；胃阴不足见口干欲饮且饮量较多，均非"},{"q":"症见口干夜甚，饥不欲食者，其病机是","o":["寒湿内盛","湿热内蕴","痰饮内停","瘀血阻滞","胃阴不足"],"a":4,"e":"胃阴不足因胃中阴液亏虚、虚火内生，故口干夜甚、饥不欲食、舌红少苔。痰饮为阴邪，内停则津液不布，故渴喜热饮而饮量不多，兼脘痞、肠鸣、舌淡苔白滑。寒湿内盛见口淡不渴；湿热内蕴见口苦口黏；痰饮内停见渴喜热饮、饮量不多；瘀血阻滞见漱水不欲咽，均非"},{"q":"突然大出血时脉象多见","o":["举之有余，按之不足","浮大无根，按之消失","浮大中空","浮而弦硬","浮而细软"],"a":2,"e":"突然大出血时阴血骤亡、阳气无所附而浮越于外，故脉浮大中空，即芤脉。胃阴不足、胃失濡养则饥不欲食，虚火扰胃则口干夜甚，兼舌红少苔、脉细数，与痰饮内停有别。举之有余、按之不足是浮脉；浮大无根、按之消失是散脉；浮而弦硬是革脉；浮而细软是濡脉，均非大出血典型脉"},{"q":"长期慢性出血，导致气血不足，脉象可见","o":["举之有余，按之不足","浮大无根，按之消失","浮大中空","浮而弦硬","浮而细软"],"a":4,"e":"长期慢性出血致气血不足、血脉不充，故脉浮而细软，即濡脉，细主血虚、软主气虚。暴崩大出血则阴血骤亡、阳气浮越，脉浮大中空而按之豁然，是芤脉的典型主病。举之有余、按之不足是浮脉；浮大无根是散脉；浮大中空是芤脉；浮而弦硬是革脉，均非气血不足之脉"},{"q":"脉象浮而细软无力是","o":["虚脉","紧脉","微脉","弱脉","濡脉"],"a":4,"e":"濡脉特征为浮而细软无力、轻取即得、重按稍减。久病出血、气血两伤，脉道不充故细，气虚不充故软而浮，与暴崩之浮大中空、芤脉空豁迥然不同。虚脉三部举按均无力；紧脉紧张有力、如转绳索；微脉极细极软、若有若无；弱脉沉而细软，均非浮而细软"},{"q":"中医诊断的基本原理中，通过外部征象而测知内在变化的是","o":["司外揣内","见微知著","以常衡变","因发知受","四诊合参"],"a":0,"e":"司外揣内即通过外在征象测知内在脏腑气血的变化，基于有诸内必形诸外。见微知著是从微小变化洞察整体；以常衡变是在认识正常基础上发现异常；因发知受是据发病推知病因；四诊合参是诊法运用原则，均非"},{"q":"中医诊断的基本原理中，在认识正常的基础上，发现异常变化的是","o":["司外揣内","见微知著","以常衡变","因发知受","四诊合参"],"a":2,"e":"以常衡变即在掌握正常标准的基础上发现异常变化，从而判断病证。司外揣内是通过外象测知内变；见微知著是从局部微小变化推知整体；因发知受是由发病推求病因；四诊合参是诊法运用原则，均非"},{"q":"气随血脱者表现为","o":["面色淡白，心悸失眠，少气懒言，乏力自汗，舌淡嫩，脉细弱","面色淡白而无华，气短乏力，伴出血，舌淡，脉细弱","面色苍白，大量出血，四肢厥冷，汗出淋漓，脉微细欲绝","面色㿠白，心悸气短，动则加剧，脉细弱结代","口唇青紫，呼吸微弱，心胸憋闷，大汗淋漓，四肢厥冷，脉微欲绝"],"a":2,"e":"气随血脱因大量出血、气随血亡，故面色苍白、大量出血、四肢厥冷、汗出淋漓、脉微细欲绝。面色淡白、心悸失眠、少气自汗是气血两虚；面白无华、气短乏力伴出血是气不摄血；㿠白、心悸气短、动则加剧是心气虚；口唇青紫、心胸憋闷、大汗厥冷是心阳暴脱，均非"},{"q":"气不摄血者表现为","o":["面色淡白，心悸失眠，少气懒言，乏力自汗，舌淡嫩，脉细弱","面色淡白而无华，气短乏力，伴出血，舌淡，脉细弱","面色苍白，大量出血，四肢厥冷，汗出淋漓，脉微细欲绝","面色㿠白，心悸气短，动则加剧，脉细弱结代","口唇青紫，呼吸微弱，心胸憋闷，大汗淋漓，四肢厥冷，脉微欲绝"],"a":1,"e":"气不摄血因气虚不能统摄血液，故面色淡白而无华、气短乏力、伴各种出血、舌淡脉细弱。面色淡白、心悸失眠、少气自汗是气血两虚；苍白、大出血、厥冷汗出是气随血脱；㿠白、心悸气短是心气虚；唇青紫、憋闷、大汗厥冷是心阳暴脱，均非"},{"q":"病室有烂苹果样气味","o":["有机磷中毒","消渴晚期","脏腑衰败","肾衰","溃腐疮疡"],"a":1,"e":"病室烂苹果样气味即丙酮味，见于消渴晚期，因血糖过高、脂肪分解产生酮体。气不摄血以气虚为本、出血为标，出血多为缓和的便血、崩漏、皮下出血，与气随血脱之暴脱不同。有机磷中毒为蒜臭味；脏腑衰败为衰败之气如肝臭；肾衰尿毒症为尿臊味；溃腐疮疡为腐臭味，均非"},{"q":"病室有蒜臭气味","o":["有机磷中毒","消渴晚期","脏腑衰败","肾衰","溃腐疮疡"],"a":0,"e":"病室蒜臭气味是有机磷农药中毒的特征性气味。消渴晚期气阴两伤、脂肪分解产生酮体，故病室有烂苹果味，为酮症酸中毒特征，与蒜臭、尿臊气味可区分。消渴晚期为烂苹果样气味；脏腑衰败为衰败之气如肝臭；肾衰尿毒症为尿臊味；溃腐疮疡为腐臭味，均非"},{"q":"实脉的脉象为","o":["状如波涛汹涌，来盛去衰","脉来数，一息五至以上","紧张有力，如转绳索","脉来流利，应指圆滑","三部脉举按均有力"],"a":4,"e":"实脉特征为三部脉举按均有力，主实证。有机磷农药可经呼吸道及皮肤吸收中毒，患者呕吐物与病室带蒜臭味，兼瞳孔缩小、大汗、肌颤可确诊。状如波涛汹涌、来盛去衰是洪脉；脉来数、一息五至以上是数脉；紧张有力、如转绳索是紧脉；脉来流利、应指圆滑是滑脉，均非实脉"},{"q":"洪脉的脉象为","o":["状如波涛汹涌，来盛去衰","脉来数，一息五至以上","紧张有力，如转绳索","脉来流利，应指圆滑","三部脉举按均有力"],"a":0,"e":"洪脉特征为状如波涛汹涌、来盛去衰、浮大有力，主气分热盛。三部脉举按均有力是实脉；脉来数、一息五至以上是数脉；紧张有力、如转绳索是紧脉；脉来流利、应指圆滑是滑脉，均非洪脉"},{"q":"嗳气酸腐，脘腹胀满，为","o":["宿食停滞","肝气犯胃","胃虚气逆","寒邪客胃","饮停胃肠"],"a":0,"e":"嗳气酸腐、脘腹胀满因宿食停滞、胃气上逆，嗳气酸腐如败卵。肝气犯胃见嗳气频作、胸胁胀痛、脉弦；胃虚气逆见嗳气低沉断续、纳呆；寒邪客胃见嗳气伴胃脘冷痛；饮停胃肠见嗳气伴肠鸣、呕吐清水，均非"},{"q":"嗳气低沉断续，兼纳呆食少","o":["宿食停滞","肝气犯胃","胃虚气逆","寒邪客胃","饮停胃肠"],"a":2,"e":"嗳气低沉断续、纳呆食少因胃气虚弱、胃失和降，故嗳气无力、声低断续。宿食停滞见嗳气酸腐、脘腹胀满；肝气犯胃见嗳气频作、胸胁胀痛；寒邪客胃见胃脘冷痛；饮停胃肠见肠鸣、呕吐清水，均非"},{"q":"胃肠虚寒，肠鸣音为","o":["脘腹痞满，肠鸣音声高","饥肠辘辘，得温则减轻","腹胀食少，肠鸣音微弱","腹胀疼痛，肠鸣音消失","胃肠鸣响，振动有水声"],"a":1,"e":"胃肠虚寒因中焦虚寒、肠鸣漉漉，故饥肠辘辘、得温则减轻。脘腹痞满、肠鸣音声高多属实证；腹胀食少、肠鸣音微弱属胃肠气虚；腹胀疼痛、肠鸣音消失属肠痹或腹膜病变；胃肠鸣响、振动有水声属饮停胃肠，均非"},{"q":"胃肠气虚，肠鸣音为","o":["脘腹痞满，肠鸣音声高","饥肠辘辘，得温则减轻","腹胀食少，肠鸣音微弱","腹胀疼痛，肠鸣音消失","胃肠鸣响，振动有水声"],"a":2,"e":"胃肠气虚因气虚推动无力、传导失司，故腹胀食少、肠鸣音微弱。脘腹痞满、肠鸣声高多属实证；饥肠辘辘、得温减轻属胃肠虚寒；腹胀疼痛、肠鸣消失属肠痹；胃肠鸣响、振动有水声属饮停胃肠，均非"},{"q":"身热夜甚，出血，动风，神昏谵语，斑疹紫黑及舌质深绛属","o":["血分实热证","血分虚热证","营分证","气分证","卫分证"],"a":0,"e":"血分实热因热入血分、动血耗血，故身热夜甚、出血、动风、神昏谵语、斑疹紫黑、舌质深绛。血分虚热见低热、暮热早凉、五心烦热；营分证见身热夜甚、舌红绛但无出血动风；气分证见壮热苔黄；卫分证见发热恶寒，均非"},{"q":"低热，暮热早凉，五心烦热，神疲欲寐，耳聋，形瘦，脉虚细属","o":["血分实热证","血分虚热证","营分证","气分证","卫分证"],"a":1,"e":"血分虚热因热入血分、耗伤阴血，故低热、暮热早凉、五心烦热、神疲欲寐、耳聋、形瘦、脉虚细。血分实热见身热夜甚、出血动风、斑疹紫黑；营分证见身热夜甚、舌红绛；气分证见壮热苔黄；卫分证见发热恶寒，均非"},{"q":"六经辨证中的“合病”指：","o":["外感病邪不经三阳经传变，而直接侵犯三阴经。","两经或三经病证同时出现。","伤寒病一经病证未解，又出现另一经的病证。","相隔一经或两经传。","表里两经之间的传变。"],"a":1,"e":"合病指两经或三经病证同时出现，如太阳阳明合病，无先后次第。外感病邪不经三阳而直犯三阴是直中；一经病证未解又现另一经是并病；相隔一经或两经而传是越经传；表里两经之间的传变是表里传，均非合病"},{"q":"六经辨证中的“并病”指：","o":["外感病邪不经三阳经传变，而直接侵犯三阴经。","两经或三经病证同时出现。","伤寒病一经病证未解，又出现另一经的病证。","相隔一经或两经传。","表里两经之间的传变。"],"a":2,"e":"并病指伤寒病一经病证未解、又出现另一经的病证，有先后次第。两经或三经病证同时出现是合病；外感病邪直犯三阴是直中；相隔一经或两经而传是越经传；表里两经之间的传变是表里传，均非并病"},{"q":"腹胀满有波动感，胁肋胀痛，右侧刺痛，食少乏力，舌紫黯有紫斑，脉弦涩，证属","o":["真寒假热证","真实假虚证","虚中夹实证","真虚假虚证","实中夹虚证"],"a":4,"e":"实中夹虚以实邪壅盛为主、兼有正气不足：腹满有波动感、胁肋胀痛、右侧刺痛、舌紫斑、脉弦涩属水饮瘀血之实，食少乏力为脾虚，故为实中夹虚。真实假虚是实邪内结反见虚象；虚中夹实以虚为主兼夹实邪；真寒假热见身热、下利清谷、脉微，均非本证"},{"q":"咳喘多年，神疲食少，胸闷心悸，现症咳喘痰多，张口抬肩，不能平卧，下肢浮肿，苔滑，脉虚数。为","o":["真寒假热证","真实假虚证","虚中夹实证","真虚假虚证","实中夹虚证"],"a":2,"e":"虚中夹实以正气虚为主、兼夹实邪：咳喘多年、神疲食少、脉虚数为虚，现症咳喘痰多、张口抬肩、不能平卧、下肢浮肿、苔滑为痰饮实邪，故为虚中夹实。实中夹虚以实邪为主；真实假虚是实邪反现虚象；真寒假热见假热之象，均非"},{"q":"肝郁化火证的脉象可见","o":["洪数脉","浮数脉","滑数脉","濡数脉","弦数脉"],"a":4,"e":"肝郁化火因肝气郁结、郁而化火，故脉见弦数，弦主肝郁、数主化火。本证宿疾正虚为本、新感痰饮为标，标本兼顾而实邪不盛，故不属虚实真假之证。洪数脉属气分热盛；浮数脉属风热表证；滑数脉属食积或痰热；濡数脉属湿热，均非肝郁化火"},{"q":"食积内热证的脉象可见","o":["洪数脉","浮数脉","滑数脉","濡数脉","弦数脉"],"a":2,"e":"食积内热因食积化热、气血涌盛，故脉见滑数，滑主食积、数主内热。肝气郁结、日久化火，弦脉主气机郁滞、数脉主里热，兼见口苦、目赤、急躁易怒、便秘尿黄。洪数脉属气分热盛；浮数脉属风热表证；濡数脉属湿热；弦数脉属肝郁化火，均非食积内热"}];
